(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{})["2kgs"]={"1":{"1":"После смерти Ахава моавитяне восстали против Израиля.","2":"Ахазия упал с верхнего этажа своего дворца в Самарии – сломался парапет. Занемог царь и послал гонцов с поручением: «Вопросите Баал – Зевува, экронского бога, суждено ли мне выздороветь?»","3":"Но Ангел Господа повелел Илие Тишбийскому выйти навстречу посланцам царя Самарии и сказать: «Разве нет Бога в Израиле, что вы идете вопрошать Баал – Зевува, экронского бога?","4":"Так говорит Господь: за это не встать тебе с постели, на которой ты лежишь. Ты умрешь!» И вышел Илия им навстречу.","5":"Посланцы возвратились к царю. Царь спросил: «Почему вы вернулись?»","6":"Они ответили: «Вышел нам навстречу человек и сказал: „Вернитесь к царю, пославшему вас, и передайте ему:, Так говорит Господь: разве нет Бога в Израиле, что ты послал вопрошать Баал – Зевува, экронского бога? За это не встать тебе с постели, на которой ты лежишь. Ты умрешь!'\"»","7":"Царь спросил: «А как выглядел тот человек, который вышел вам навстречу и сказал это?»","8":"Ему ответили: «В овчине. А на бедрах – кожаный пояс». – «Это Илия Тишбийский!» – сказал царь","9":"и послал за ним начальника полусотни вместе с полусотенным отрядом. Начальник полусотни пришел к Илие, сидевшему на вершине горы. «Человек Божий! – сказал он Илие. – Царь приказывает тебе: „Сойди!\"»","10":"Илия ответил: «Если я и вправду человек Божий, пусть огонь сойдет с неба и испепелит тебя с твоим отрядом!» И сошел огонь с неба, и испепелил начальника полусотни и весь его отряд.","11":"Царь послал другого начальника полусотни с другим полусотенным отрядом. Тот пришел и сказал Илие: «Человек Божий! Царь приказывает тебе: „Сойди немедленно!\"»","12":"Илия ответил: «Если я и вправду человек Божий, пусть огонь сойдет с неба и испепелит тебя с твоим отрядом!» И сошел с неба огонь Божий, и испепелил начальника полусотни и весь его отряд.","13":"Царь послал третьего начальника полусотни с новым полусотенным отрядом. Тот пришел, пал на колени перед Илией и взмолился: «Человек Божий! Пощади мою жизнь и жизнь рабов твоих – вот этого отряда!","14":"Двух начальников, вместе с их отрядами, испепелил огонь, сошедший с неба! Пощади мою жизнь!»","15":"И ангел Господа велел Илие: «Спускайся. Иди с ним, не бойся его». Илия пришел к царю, вместе с начальником полусотни,","16":"и сказал: «Так говорит Господь: за то, что ты послал вопросить Баал – Зевува, экронского бога (будто в Израиле нет Бога, которого можно вопросить!) – не встать тебе с постели, на которой ты лежишь. Ты умрешь!»","17":"И Ахазия умер; исполнилось слово Господа, возвещенное Илией. Царем после него стал Иорам, так как у Ахазии не было сына. (Это случилось во второй год правления царя Иудеи Иорама, сына Иосафата).","18":"Прочее о деяниях Ахазии написано в «Летописях царей Израиля»."},"2":{"1":"Вот как Господь вознес Илию на небо в ураганном вихре. Илия и Елисей шли вместе из Гилгала.","2":"«Оставайся здесь, – сказал Илия Елисею, – а меня Господь посылает в Бет – Эль». – «Клянусь Господом и клянусь твоей жизнью, – отвечал Елисей, – я не оставлю тебя!» И они вместе пошли в Бет – Эль.","3":"Вышли к Елисею пророки из пророческой братии Бет – Эля и сказали ему: «Знаешь ли ты, что сегодня Господь заберет от тебя твоего господина?» – «Знаю, – отвечал Елисей. – Молчите!»","4":"Илия сказал Елисею: «Оставайся здесь, а меня Господь посылает в Иерихон». – «Клянусь Господом и клянусь твоей жизнью, – отвечал Елисей, – я не оставлю тебя!» И они вместе пришли в Иерихон.","5":"Подошли к Елисею пророки из пророческой братии Иерихона и сказали ему: «Знаешь ли ты, что сегодня Господь заберет от тебя твоего господина?» – «Знаю, – отвечал Елисей. – Молчите!»","6":"Илия сказал Елисею: «Оставайся здесь, а меня Господь посылает к Иордану». – «Клянусь Господом и клянусь твоей жизнью, – ответил Елисей, – я не оставлю тебя!» И они пошли вместе.","7":"Пятьдесят человек из пророческой братии последовали за ними и встали поодаль. Илия и Елисей остановились возле Иордана.","8":"Илия взял свою мантию, свернул ее и ударил по воде. Вода расступилась, и они перешли реку посуху.","9":"Когда они перешли реку, Илия сказал Елисею: «Скажи, что ты хочешь, чтобы я для тебя сделал, пока я еще с тобой?» Елисей ответил: «Пусть от духа твоего я унаследую двойную долю». –","10":"«Трудна твоя просьба, – сказал Илия. – Если увидишь, как Он забирает меня, то сбудется твое желание, а если не увидишь – не сбудется».","11":"Так шли они, говорили друг с другом. И вдруг видят – огненные колесницы и кони огненные! Разлучили их колесницы и кони: Илия, в вихре, вознесся на небо,","12":"а Елисей смотрел и кричал: «Отец мой, отец мой! Колесницы и кони Израилевы!» Илия скрылся из глаз. И тогда Елисей разодрал свои одежды надвое.","13":"Потом подобрал упавшую мантию Илии и вернулся на берег Иордана.","14":"Держа в руках мантию Илии, он ударил ею по воде и воскликнул: «Где же Он, Господь, Бог Илии?» Подобно Илие, ударил он по воде – расступилась вода, и Елисей перешел реку посуху.","15":"Когда стоявшие поодаль пророки из пророческой братии Иерихона это увидели, то сказали: «Дух Илии – на Елисее!» Они вышли ему навстречу и пали ниц пред ним.","16":"«Среди нас, рабов твоих, – сказали они Елисею, – есть пятьдесят человек сильных и крепких. Пусть пойдут они поищут твоего господина. Быть может, дух Господень, словно ветер, подхватил его и бросил на какую-нибудь гору или в какое-нибудь ущелье». – «Не надо им идти», – сказал Елисей.","17":"Но они настаивали до тех пор, пока он не разрешил: «Пусть идут». Отрядили на поиски пятьдесят человек. Три дня искали они, но не нашли.","18":"Вернулись к Елисею – тот был в Иерихоне – и он сказал: «Говорил же я вам: не ходите».","19":"Жители этого города обратились к Елисею: «Господин, город наш расположен удобно, сам видишь, да только вода плоха и земля бесплодна».","20":"Он сказал им: «Принесите мне новую миску, а в миску насыпьте соли». Так и сделали.","21":"Он вышел к источнику, бросил в него соли и сказал: «Так говорит Господь: Я исцеляю эту воду. Впредь не будет здесь ни мора, ни бесплодия».","22":"С того времени и до сих пор вода там здоровая – исполнилось слово, сказанное Елисеем.","23":"Оттуда Елисей пошел в Бет – Эль. Когда он шел по дороге, из города выбежали мальчишки и стали дразнить его: «Пошел, плешивый! Пошел, плешивый!»","24":"Обернулся он, посмотрел на детей и проклял их именем Господа. Вышли из леса две медведицы и напали на детей: сорок два мальчика из их числа были растерзаны.","25":"Елисей же пошел оттуда на гору Кармил, а затем вернулся в Самарию."},"3":{"1":"Иорам, сын Ахава, стал царем Израиля в восемнадцатый год царствования Иосафата, царя Иудеи. Царствовал он двенадцать лет.","2":"И творил он дела, ненавистные Господу, хотя и меньше, чем отец его и мать; он даже убрал священный камень Ваала, поставленный его отцом.","3":"Но он по – прежнему был привержен тем грехам, в которые вверг израильтян Иеровоам, сын Невата. Не отвратился Иорам от этих грехов.","4":"Меша, царь Моава, держал овечьи стада. Он посылал царю Израиля дань: сто тысяч ягнят и шерсть ста тысяч баранов.","5":"Но после смерти Ахава царь Моава восстал против царя Израиля.","6":"Выступил царь Иорам из Самарии во главе всего израильского войска","7":"и велел передать Иосафату, царю Иудеи: «Царь Моава восстал против меня. Пойдешь ли со мной против Моава?» – «Пойду, – ответил тот. – Куда ты – туда и я, куда твое войско – туда и мое, куда твои кони – туда и мои».","8":"И он спросил: «Какой дорогой мы пойдем?» – «Через Эдомскую пустыню», – ответил тот.","9":"Царь Израиля, царь Иудеи и царь Эдома выступили в поход. Семь дней шли они кружным путем; и не осталось у них воды для войска и для животных в обозе.","10":"«Беда! – сказал царь Израиля. – Господь призвал сюда троих царей, чтобы предать в руки моавитян!»","11":"Иосафат спросил: «Нет ли здесь кого-нибудь из пророков Господних? Мы бы через него вопросили Господа». Один человек из свиты царя израильского ответил: «Здесь Елисей, сын Шафата, – тот самый, что возливал воду на руки Илие».","12":"Иосафат сказал: «Через него возвестит Господь свое слово!» Царь Израиля, вместе с Иосафатом и царем Эдома пошли к Елисею.","13":"«Что тебе надо от меня? – сказал Елисей царю Израиля. – Ступай к пророкам своего отца и к пророкам своей матери!» – «Не говори так, – ответил царь Израиля. – Господь завел нас, троих царей, в это место, чтобы предать в руки моавитян!»","14":"Елисей сказал: «Клянусь Господом Воинств, которому я служу: если бы не уважал я Иосафата, царя Иудеи, то я и глядеть бы на тебя не стал, и видеть бы тебя не видел.","15":"…Позовите ко мне музыканта». Когда музыкант играл, рука Господня касалась Елисея.","16":"И возвестил Елисей: «Так говорит Господь: копайте ямы в долине, ямы для воды!","17":"Так говорит Господь: ветра вы не заметите и ливня не увидите, а долина наполнится водою! Напьетесь и вы, и ваш скот, и ваши вьючные животные.","18":"Но это еще не все, что сделает для вас Господь: Он предаст моавитян в ваши руки!","19":"Вы разрушите все их твердыни и все их цветущие города, все их плодовые деревья вы срубите, все источники засыплете, все плодородные поля их вы забросаете камнями, чтобы они стали бесплодными!»","20":"Наступило утро, час, когда приносят жертву, – и стало видно, что со стороны Эдома течет вода, затопляя всю округу.","21":"А моавитяне, узнав, что цари идут на них войною, созвали всех, кто мог носить оружие. Выступило их войско и остановилось у границы.","22":"Рано утром, когда первые лучи солнца упали на воду, моавитянам издали она показалась красной, как кровь.","23":"«Это кровь! – решили они. – Видно, цари стали биться друг с другом и друг друга перебили. На добычу, Моав!»","24":"И они устремились к израильскому стану. Тогда израильтяне бросились в бой и разбили их. Моавитяне обратились в бегство. Израильтяне преследовали их по пятам и убивали.","25":"Города моавитян они стерли с лица земли и все плодородные поля забросали камнями – каждый воин кинул по камню. Все источники засыпали, все плодовые деревья срубили. Нигде, кроме Кир – Харесета, не осталось камня на камне. Пращники окружили город и стали его обстреливать.","26":"Когда царь Моава увидел, что враг одолевает его, то, собрав вокруг себя семьсот воинов, владеющих мечом, он попытался прорваться к царю Эдома, – но не смог.","27":"Тогда взял он своего первенца, наследника престола, и принес его в жертву всесожжения на городской стене. Гнев небесный обрушился на израильтян – они отступили и вернулись в свою страну."},"4":{"1":"Вдова одного человека из пророческой братии пришла к Елисею, крича и плача: «Мой муж, раб твой, умер. Ты ведь знаешь, что он, раб твой, чтил Господа! А теперь тот, кому мы задолжали, хочет забрать в рабство обоих моих сыновей!» –","2":"«Чем я могу помочь тебе? – сказал Елисей. – Скажи, что у тебя в доме осталось?» – «У меня, рабы твоей, в доме пусто, – отвечала она. – Есть только маленький кувшинчик оливкового масла». –","3":"«Пройди по улице, – сказал он, – и попроси у соседок кувшины. Пустых кувшинов, да побольше!","4":"Потом запрись с сыновьями в доме и разливай масло по всем кувшинам. Как наполнится кувшин – отставляй его в сторону».","5":"Вернулась она к себе и заперлась с сыновьями. Они стали подносить кувшины, а она – разливать.","6":"Так все кувшины и наполнились. «Неси следующий!» – говорит она сыну. Тот отвечает: «Нет больше кувшинов». И масло кончилось. Юна пошла, рассказала все человеку Божьему, и он велел: «Пойди продай масло и заплати долг. А того, что останется, хватит на жизнь и тебе, и твоим сыновьям».","8":"Однажды Елисей пришел в Шунем. Была там одна богатая женщина; она уговорила его зайти к ней поесть. С тех пор всякий раз как Елисей бывал в тех краях, он заходил к ней поесть.","9":"Однажды она сказала мужу: «Я знаю: этот путник, что всегда гостит у нас, – святой человек Божий.","10":"Давай устроим ему наверху комнатку, поставим там кровать, стол, стул и светильник. И когда он будет приходить к нам, пусть располагается там».","11":"Однажды, когда он пришел к ним, расположился в этой комнатке и лег,","12":"он велел своему слуге Гиезию: «Позови эту шунамитянку». Тот позвал ее. Она предстала перед Елисеем,","13":"и он велел Гиезию: «Скажи ей: „Я вижу, как трепетно ты заботишься о нас. Что сделать для тебя? Может, тебе нужно, чтоб за тебя замолвили слово перед царем или военачальником?\"» – «Мои родные заботятся обо мне», – отвечала она.","14":"«Что сделать для нее?» – спросил Елисей. Гиезий ответил: «Сына у нее нет! А муж – уже старик». –","15":"«Позови ее», – велел ему Елисей. Тот позвал ее, она встала у порога.","16":"Елисей сказал: «На будущий год, в это самое время, ты будешь прижимать к своей груди сына!» – «О господин мой, человек Божий! – отвечала она. – Не надо обманывать меня, рабу твою!»","17":"Но она зачала, и на следующий год, в предсказанный срок, родила. Все было, как говорил ей Елисей.","18":"Мальчик подрос. Однажды он пришел к отцу (тот был в поле, со жнецами)","19":"и вдруг сказал: «Голова! Моя голова!» – «Отнеси его к матери», – велел отец работнику.","20":"Тот подхватил мальчика и отнес к матери. До полудня он был у нее на коленях, а в полдень умер.","21":"Мать отнесла его наверх и положила на кровать человека Божьего, потом затворила дверь, вышла наружу,","22":"позвала своего мужа и сказала: «Дай мне кого-нибудь из слуг и ослицу. Я быстро съезжу к человеку Божьему и вернусь». –","23":"«Зачем тебе ехать к нему сегодня? – спросил муж. – Нынче ведь не новолуние, не суббота…» – «Все хорошо», – отвечала она.","24":"Оседлав ослицу, она велела слуге: «Погоняй ослицу без устали! Не останавливайся, пока не скажу».","25":"Она отправилась в путь и приехала к человеку Божьему на гору Кармил. Увидав ее издали, человек Божий сказал своему слуге Гиезию: «Смотри-ка, шунамитянка!","26":"Беги ей навстречу и спроси, как она поживает, как поживает муж, как сын?» – «Все хорошо», – отвечала она.","27":"Она взошла на гору к человеку Божьему, и пав ниц, припала к его ногам. Гиезий хотел оттолкнуть ее, но человек Божий сказал: «Оставь ее, у нее горе. А Господь скрыл это от меня, не сказал мне». –","28":"«Господин мой, – промолвила она, – разве я выпрашивала себе сына у тебя? Не надо, говорила я, не обнадеживай меня!»","29":"Елисей приказал Гиезию: «Подпояшься, возьми мой посох и отправляйся в путь; если встретишь кого – не здоровайся, поздороваются с тобой – не отвечай. Посох мой приложишь к лицу мальчика».","30":"Но мать мальчика сказала: «Клянусь Господом и клянусь твоей жизнью, я не отойду от тебя!» Тогда Елисей собрался и сам пошел вместе с ней.","31":"Гиезий пришел первым. Он приложил посох к лицу мальчика – ни звука, ни ответа. Гиезий вышел навстречу Елисею и сообщил ему: «Не пробудился мальчик».","32":"Вошел Елисей в дом и видит: на его кровать положили мертвого ребенка.","33":"Он зашел в комнату, затворил дверь, остался с ним в комнате наедине и помолился Господу.","34":"Потом подошел к кровати и лег на тело мальчика, приложил губы к губам, глаза – к глазам, ладони – к ладоням. Так припал он к нему, и тело мальчика стало теплеть.","35":"Елисей снова походил туда – сюда по комнате, подошел к кровати, снова припал к мальчику, и тот чихнул – раз, другой… семь раз. Потом открыл глаза.","36":"Елисей подозвал Гиезия и велел ему: «Зови шунамитянку!» Тот позвал ее, и она вошла. «Забирай своего сына», – сказал Елисей.","37":"Подошла она, пала ему в ноги, простерлась перед ним на земле, потом взяла сына и вышла из комнаты.","38":"А Елисей вернулся в Гилгал. По всей стране был тогда голод. Люди из пророческой братии собрались вокруг Елисея. Он велел своему слуге: «Поставь на огонь большой котел и свари похлебку для всех».","39":"А перед тем один человек пошел в поле собрать съедобных трав и наткнулся на дикую тыкву. Не зная, что это, он набрал ее плодов в подол рубахи и, вернувшись, накрошил в котел с похлебкой.","40":"Стали разливать похлебку. Но когда принялись за еду, закричали: «В этом котле – смерть! Человек Божий!» И побоялись есть.","41":"Елисей сказал: «Дайте мне муки». Всыпал муку в котел и велел: «Разливай, пусть едят». Ничего вредного не было больше в котле.","42":"Один человек из Баал – Шалиши пришел и принес человеку Божьему хлеб нового урожая: двадцать ячменных хлебов и колосья со спелым зерном. Человек Божий велел: «Раздай людям, пусть едят».","43":"Слуга спросил: «Как? Раздать вот это на сто человек?» – «Раздай, – отвечал тот. – Пусть едят. Так говорит Господь: наедятся, и еще останется!»","44":"Слуга раздал. Все наелись, и даже еще осталось – так исполнилось слово Господа."},"5":{"1":"Нааман, полководец арамейского царя, был у своего господина в большом почете, потому что через Наамана Господь даровал арамеям победы. Но этот доблестный воин был болен – поражен проказой.","2":"В один из своих набегов на Израиль арамеи угнали в плен маленькую девочку. Она стала служанкой у жены Наамана.","3":"«Если бы хозяин мог сходить к пророку, что в Самарии, – сказала она своей госпоже, – тот избавил бы его от проказы!»","4":"Нааман передал своему владыке слова девочки, приведенной из Израиля,","5":"и царь Арама сказал Нааману: «Ступай! Я дам тебе письмо к царю Израиля». Нааман пустился в путь, взяв с собою десять талантов серебра, шесть тысяч шекелей золота и десять перемен одежд.","6":"Он пришел к царю Израиля и вручил письмо, в котором говорилось: «…Вместе с этим письмом я посылаю к тебе Наамана, моего верного слугу, чтобы ты избавил его от проказы».","7":"Прочитав это письмо, царь Израиля разодрал одежды и сказал: «Разве я Бог, который посылает смерть и дарует жизнь? А он требует, чтобы я избавил человека от проказы! Сами посудите, сами посмотрите – он ищет предлог для ссоры!»","8":"Услышав, что царь Израиля разодрал одежды, Елисей, человек Божий, велел передать царю: «Зачем раздирать одежды? Пусть придет этот человек ко мне – и увидит, что есть пророк в Израиле!»","9":"И вот пришел Нааман, со всеми своими конями и колесницами, и встал перед домом, в ожидании Елисея.","10":"Тот велел передать ему: «Ступай, семь раз окунись в Иордан – и твое тело исцелится от проказы, ты будешь чист».","11":"Нааман в гневе повернулся и пошел прочь, говоря: «Я-то думал, что он ко мне выйдет, станет, призовет имя своего Бога, Господа, поводит рукой над болячками, исцелит от проказы…","12":"Амана и Парпар, что текут под Дамаском, будут получше всех рек израильских! Уж лучше тогда мне в них окунуться, чтобы очиститься от проказы!» Он в ярости пошел прочь,","13":"но люди из его свиты подошли к нему и сказали: «Отец наш! Если бы пророк велел тебе исполнить что-нибудь трудное – разве ты не исполнил бы? А он лишь сказал тебе: „Окунись, и очистишься от проказы\"».","14":"Тогда пошел Нааман, окунулся в Иордан семь раз, как велел человек Божий, – и стала его кожа как у малого ребенка, чиста от проказы.","15":"Вернулся он, со всем своим отрядом, к человеку Божьему, подошел, стал перед ним и сказал: «Теперь я понял, что нет на земле Бога нигде, кроме страны Израильской. Прими же дары от меня, раба твоего». –","16":"«Клянусь Господом, которому я служу, – не возьму даров», – отвечал тот. Нааман его уговаривал, но тот отказался.","17":"«Что ж, раз не хочешь… – сказал Нааман, – но пусть насыплют мне, рабу твоему столько земли, сколько сможет увезти пара мулов… Я, раб твой, впредь не буду приносить всесожжения и жертвы никаким богам, кроме Господа.","18":"Только одну вещь пусть простит Господь мне, рабу твоему: когда мой владыка пойдет в храм Риммона, чтоб совершить там поклонение – а я сопровождаю его, веду под руку, – то и мне придется совершить поклонение в храме Риммона. Когда я буду поклоняться в храме Риммона – пусть Господь простит это мне, рабу твоему». –","19":"«Ступай с миром», – ответил Елисей. Нааман успел уже отойти достаточно далеко,","20":"когда Гиезий, слуга Елисея, человека Божьего, подумал: «Что же хозяин ничего не взял у этого арамея, Наамана, из даров, которые он принес! Господом клянусь, надо мне догнать его и взять что-нибудь!»","21":"И Гиезий побежал догонять Наамана. Увидел Нааман, что тот бежит за ним, сошел с колесницы и направился ему навстречу: «Что-нибудь случилось?» – спросил он у Гиезия.","22":"«Все в порядке, – отвечал тот. – Хозяин велел передать вам: „Ко мне пришли двое юношей с Ефремовых гор, из пророческой братии. Дай мне для них талант серебра и две перемены одежды!\"» –","23":"«Сделай милость, – отвечал Нааман, – возьми два таланта!» Он стал упрашивать Гиезия, велел сложить серебро – два таланта – в две сумы, и дал их вместе с двумя переменами одежд двум слугам. Те пошли вместе с Гиезием, неся дары.","24":"Когда они приблизились к городу, Гиезий взял у них подарки и сложил у себя дома, а слуг Наамана отпустил.","25":"И предстал перед хозяином. «Откуда ты, Гиезий?» – спросил Елисей. «Я, раб твой, никуда не отлучался», – ответил тот.","26":"Елисей сказал: «Думаешь, сердце мое не следовало за тобой, когда этот человек сошел с колесницы и направился тебе навстречу? Разве время сейчас приобретать серебро и одежды, или оливковые рощи и виноградники, или овец и коров, или рабов и рабынь!","27":"Пусть же Нааманова проказа навеки перейдет на тебя и на потомков твоих!» И вышел от него Гиезий весь в струпьях, как в снегу."},"6":{"1":"Пророческая братия стала говорить Елисею: «Дом, где мы живем под твоим началом, тесен для нас.","2":"Пойдем к Иордану, заготовим там каждый по бревну, и построим себе новое помещение, будем там жить». – «Ступайте», – сказал Елисей.","3":"«Сделай милость, – сказал один из них, – пойди и ты с нами, рабами твоими!» – «Хорошо, – отвечал Елисей, – пойдем».","4":"И пошел с ними. Они пришли на берег Иордана, стали рубить деревья,","5":"и случилось так, что когда один из них валил дерево, его топор слетел с топорища прямо в воду. «Беда, господин мой! – закричал он. – Топор-то не мой, я его одолжил!» –","6":"«Куда он упал?» – спросил человек Божий. Тот показал ему место. Человек Божий вытесал топорище, бросил в воду на том месте – и топор всплыл.","7":"«Вынимай», – сказал он. Тот протянул руку и вытащил топор из воды.","8":"Царь Арама воевал с Израилем. Всякий раз когда он на совете говорил своим приближенным: «Ведите войска в такое-то место» –","9":"тут же человек Божий посылал предупредить царя израильского: «Берегись, в этом месте не показывайся, туда идут арамеи».","10":"А царь израильский посылал предупредить жителей того места, о котором ему говорил человек Божий. Так было не раз и не два: человек Божий предупреждал царя и тот был начеку.","11":"Рассвирепел царь Арама, созвал своих приближенных и говорит им: «Отвечайте: кто из наших доносит царю Израиля?» –","12":"«Никто, господин мой царь, – ответил один из вельмож, – просто израильский пророк Елисей может пересказать царю Израиля даже то, что ты говоришь у себя в спальне».","13":"Царь приказал: «Ступайте, разузнайте, где он сейчас, – и я пошлю людей схватить его». Царю сообщили, что Елисей в Дотане,","14":"и он послал туда коней, колесницы – огромное войско. Пришли они ночью и окружили город.","15":"Рано утром встал слуга человека Божьего, вышел из дому и видит: город окружен войсками – кони, колесницы. «Беда, господин! – говорит он Елисею. – Что нам делать?» –","16":"«Не бойся, – отвечал Елисей. – Тех, кто за нас, больше, чем тех, кто за них!»","17":"Елисей помолился: «Господь, открой ему глаза, пусть увидит!» Господь открыл слуге глаза, и тот увидел – всюду на холме вокруг Елисея кони и колесницы огненные.","18":"Когда арамеи подошли, Елисей помолился Господу: «Порази это племя слепотой!» И Господь поразил арамеев слепотой – исполнилось прошение Елисея.","19":"А Елисей сказал арамеям: «Не по той дороге вы пошли и не в тот город попали. Идите за мной, я отведу вас к тому, кого вы ищете». И повел их в Самарию.","20":"Когда они пришли в Самарию, Елисей сказал: «Господь, открой им глаза, пусть увидят!» И Господь открыл им глаза. Смотрят – они посреди Самарии!","21":"Увидев их, царь Израиля спросил у Елисея: «Отец мой, может быть, перебить их всех?» –","22":"«Не убивай их, – отвечал Елисей. – Разве своим мечом и луком ты взял их в плен, что хочешь перебить их? Дай им хлеба, воды, пусть едят и пьют, а потом пусть возвращаются к своему господину».","23":"И устроил им царь большой пир. Они ели и пили, а потом царь отпустил их, и они вернулись к своему господину. После этого арамеи перестали устраивать набеги на Израиль.","24":"Через некоторое время Бен – Хадад, царь Арама, собрав все свое войско, пошел на Самарию и осадил ее.","25":"В Самарии начался страшный голод. Осада довела горожан до того, что ослиную голову продавали за восемьдесят серебряных шекелей, а четверть кава голубиного помета – за пять шекелей.","26":"Когда царь Израиля шел по городской стене, к нему бросилась, крича, какая-то женщина: «Помоги мне, господин мой царь!» –","27":"«Не проси… – ответил царь, – Господь да поможет тебе! А я – что и откуда я возьму, чтобы помочь тебе? Хлеб с гумна? Вино из давильни?","28":"…Ну что за прошение у тебя?» – сказал царь. И она ответила: «Вот эта женщина мне говорила: „Принеси своего сына, и мы сегодня его съедим, а завтра съедим моего сына!\"","29":"Мы с ней вместе сварили моего сына и съели. На другой день я говорю ей: „Теперь твоего съедим, приноси\". А она его спрятала!»","30":"Услышал царь слова женщины – и разодрал на себе одежду. Он стоял в это время на городской стене, и все увидели, что под одеждой, на теле у него была дерюга.","31":"И сказал царь: «Пусть так-то и так-то покарает меня Бог – если сегодня же не слетит голова с плеч Елисея, сына Шафата!»","32":"Елисей сидел у себя дома, в кругу старейшин. Царь послал к нему одного из своих вельмож; но еще прежде, чем тот пришел, Елисей сказал старейшинам: «Смотрите-ка – он, этот сын убийцы, посылает человека отрубить мне голову! Как придет его посланец, захлопните дверь и держите крепко, не пускайте. А вот уже слышны и шаги его господина, идущего за ним…»","33":"Не успел он договорить, как явился царь. «Посмотри, – сказал он, – какое бедствие послал нам Господь! Чего еще ждать мне от Господа?»"},"7":{"1":"«Слушайте слово Господа! – возвестил Елисей. – Так говорит Господь: завтра же у ворот Самарии будут продавать меру пшеничной муки за шекель и две меры ячменной муки – за шекель».","2":"Телохранитель, который сопровождал царя и вел его под руку, сказал человеку Божьему: «Пусть даже Господь откроет створы небесные – не может это пророчество сбыться!» И ответил Елисей: «Ты увидишь это своими глазами – да не отведаешь!»","3":"В ту пору у самых городских ворот сидели четверо прокаженных. Они сказали друг другу: «Что мы сидим тут, ждем своей смерти?","4":"Если решимся пойти в город – там голод, мы умрем. Здесь останемся – умрем. Давайте перебежим к арамеям. Пощадят они нас – будем жить, убьют – значит убьют».","5":"Когда стемнело, они отправились к стану арамеев. Подошли, смотрят, а там – никого.","6":"Господь устроил так, что арамейскому войску послышались грохот колесниц, топот конницы – шум огромной рати. Арамеи сказали друг другу: «Это царь Израиля подкупил хеттских и египетских царей, чтобы они напали на нас!»","7":"И под покровом темноты они бежали прочь, оставив все, как было: шатры, лошадей, ослов, весь стан – бежали, спасая жизнь.","8":"Пришли прокаженные к краю арамейского стана, заглянули в один из шатров, поели, попили, набрали там серебра, золота, одежды, пошли и спрятали. Потом вернулись, заглянули в другой шатер, набрали добра и там, пошли и спрятали.","9":"Затем говорят друг другу: «Нет, не то мы делаем! Сегодня день радостной вести, а мы ее никому не возвещаем. Грех нам тянуть до рассвета! Пойдем, расскажем обо всем во дворце».","10":"Они подошли к городским воротам, позвали стражу и стали рассказывать: «Мы были в стане арамеев. Там нет никого, тишина. Лошади и ослы на привязи, шатры стоят – все как положено».","11":"Стражники кликнули людей, велели сообщить во дворец.","12":"Царь, встав среди ночи, обратился к своим приближенным: «Я скажу вам, что подстроили арамеи. Им известно, что у нас голод, поэтому они покинули стан и спрятались в поле. Думают про нас: „Вот выйдут они из города, тут-то мы их и схватим живьем, а потом вступим в город\"».","13":"Один из приближенных ответил: «Возьмем пяток лошадей из тех, что есть еще в городе. Помирают они, как и весь народ израильский… Пошлем кого-нибудь, пусть посмотрят, что там…»","14":"Царь велел снарядить две колесницы и послал их по следам арамейского войска со словами: «Поезжайте, посмотрите, что там».","15":"Колесницы доехали до самого Иордана, и по всей дороге валялись одежда и утварь, брошенные арамеями в спешке. Посланцы вернулись и доложили об этом царю.","16":"Тогда вышел народ из города и стал грабить арамейский стан. И вот уже продают меру пшеничной муки за шекель, и две меры ячменной муки – за шекель. Исполнилось слово Господа.","17":"А стоять на страже у ворот Самарии царь поручил тому самому телохранителю, который сопровождал его и вел под руку. И толпа затоптала его насмерть у ворот, как и предсказал человек Божий, когда царь приходил к нему.","18":"Все сбылось, что говорил царю человек Божий. Он сказал: «Завтра же у ворот Самарии две меры ячменя будут продавать за шекель и меру пшеничной муки – за шекель!»","19":"А телохранитель ответил тогда человеку Божьему: «Пусть даже Господь откроет створы небесные – не может это пророчество сбыться!» И Елисей сказал: «Ты увидишь это своими глазами – да не отведаешь!»","20":"Так и случилось: толпа затоптала его у ворот насмерть."},"8":{"1":"Елисей сказал той женщине, у которой воскресил сына: «Собирайся в путь, уходи отсюда со всей своей семьей, ищи пристанища, где хочешь, потому что Господь повелел быть голоду – семь лет будет длиться голод в этом краю».","2":"Она сделала так, как велел ей человек Божий: собралась и ушла со всей своей семьей. Найдя себе пристанище в стране филистимлян, она прожила там семь лет.","3":"А через семь лет, вернувшись из страны филистимлян, пошла к царю просить, чтобы ей вернули дом и поле.","4":"Как раз в это время царь беседовал с Гиезием, слугой человека Божьего. «Расскажи мне, – попросил его царь, – о всех тех великих чудесах, которые сотворил Елисей».","5":"И вот, когда Гиезий рассказывал, как Елисей воскресил мертвого, – женщина, у которой Елисей воскресил сына, пришла просить, чтобы ей вернули дом и поле. Гиезий сказал: «Вот та самая женщина, господин мой царь! А вот и ее сын, воскрешенный Елисеем!»","6":"Царь стал ее расспрашивать, и она рассказала ему все как было. Царь поручил одному из евнухов позаботиться о ней: «Проследи, – сказал он, – чтобы ей вернули все, что у нее было, и чтобы отдали весь доход, какой принесло ее поле со времени ее ухода до сего дня».","7":"Елисей пришел в Дамаск. В ту пору Бен – Хадад, царь Арама, был болен. Ему сказали: «Сюда пришел человек Божий».","8":"Царь велел Хазаэлу: «Приготовь дары и ступай к человеку Божьему. Вопроси через него Господа, суждено ли мне поправиться».","9":"Хазаэл приготовил дары и пошел к человеку Божьему. Сорок верблюдов везли Елисею все, чем богат Дамаск. Пришел он, стал перед человеком Божьим и сказал: «Бен – Хадад, царь Арама, сын твой, послал меня к тебе спросить, суждено ли ему поправиться».","10":"Елисей ответил: «Пойди скажи ему: „Ты поправишься\". Но Господь открыл мне, что ему суждено умереть».","11":"И застыло лицо его, взгляд стал неподвижным. Наконец человек Божий заплакал.","12":"«Господин мой, почему ты плачешь?» – спросил Хазаэл. Тот ответил: «Потому что я знаю, сколько зла ты принесешь израильтянам. Твердыни их ты сожжешь дотла, юношей мечом сразишь, младенцев будешь рубить на куски, беременным – вспарывать животы!» –","13":"«Кто я, чтобы совершать такие подвиги? – спросил Хазаэл. – Я раб твой, жалкий пес…» – «Господь явил мне видение, – сказал Елисей, – ты царь Арама!»","14":"Оставив Елисея, Хазаэл вернулся к своему господину. «Что сказал Елисей?» – спросил тот. «Он сказал мне, что ты непременно поправишься», – отвечал Хазаэл.","15":"А на следующий день он взял одеяло, намочил водой и накрыл им лицо больного. Тот задохнулся. Хазаэл стал царем.","16":"На пятый год царствования Иорама, сына Ахава, царя израильского, (в Иудее тогда царствовал Иосафат) царем Иудеи стал Иорам, сын Иосафата.","17":"Когда Иорам стал царем, ему было тридцать два года. Он царствовал в Иерусалиме восемь лет.","18":"Он шел по пути царей Израиля, делал то же самое, что и весь род Ахава – ведь его жена была дочерью Ахава. Творил он дела, ненавистные Господу.","19":"Но ради Давида, раба Своего, Господь решил не губить Иудею: ведь Господь пообещал Давиду, что светильник его рода вовек не угаснет.","20":"При Иораме эдомитяне восстали и вышли из-под власти Иудеи и поставили себе собственного царя.","21":"Иорам со своим колесничным войском дошел до Цаира. Там, ночью, он разбил эдомитян, окруживших его, вместе с его колесничными отряда – ми, но после этого иудейское войско разбежалось по домам.","22":"С тех пор и доныне Эдом не подчиняется Иудее. Тогда же от Иудеи отделилась и Ливна .","23":"Прочее о деяниях Иорама написано в «Летописях царей Иудеи».","24":"И упокоился Иорам со своими предками – был похоронен вместе с предками в Городе Давидовом. Царем после него стал его сын Ахазия.","25":"На двенадцатый год царствования Иорама, сына Ахава, царя израильского, царем Иудеи стал Ахазия, сын Иорама.","26":"Когда Ахазия стал царем, ему было двадцать два года. Он царствовал в Иерусалиме один год. Его мать – Гофолия, из рода Омри, царя израильского.","27":"Он шел по пути Ахавова рода. Как и весь род Ахава, он творил дела, ненавистные Господу – он сам был из Ахавова рода.","28":"Вместе с Иорамом, сыном Ахава, Ахазия двинулся на Рамот Галаадский воевать с Хазаэлом, царем Арама. Но арамеи разбили Иорама.","29":"Иорам вернулся в Изреель залечивать раны, полученные от арамеев в Рамоте, где он сражался с Хазаэлом, царем Арама. Иудейский царь Ахазия, сын Иорама, тоже отправился в Изреель – навестить раненого Иорама, сына Ахава."},"9":{"1":"Пророк Елисей позвал одного человека из пророческой братии и сказал ему: «Подпояшься, возьми вот этот сосуд с оливковым маслом и иди в Рамот Галаадский.","2":"Когда придешь, найди там Иегу, сына Иосафата, из рода Нимши. Подойди к нему, отзови в сторону и пройди с ним в самую дальнюю комнату.","3":"Там возлей на его голову масло из флакона и скажи: „Так говорит Господь: этим помазанием Я возвожу тебя в цари Израиля\". Потом распахни дверь и убегай прочь без оглядки».","4":"И пошел этот юноша из пророческой братии в Рамот Галаадский.","5":"Пришел, смотрит – сидят военачальники. «У меня к тебе дело, полководец», – сказал он. «К кому из нас?» – спросил Иегу. Тот ответил: «К тебе, полководец».","6":"Иегу встал и вошел вместе с ним внутрь дома. Тот возлил на его голову масло и сказал: «Так говорит Господь, Бог Израиля: этим помазанием Я возвожу тебя в цари Израиля, народа Господнего;","7":"ты уничтожишь весь род Ахава, твоего господина, – так отомщу Я за кровь пророков, рабов Моих, и за кровь всех рабов Господних, убитых Иезавелью.","8":"Пусть сгинет весь род Ахава! Я истреблю в Израиле всех мужчин из рода Ахава, от мала до велика!","9":"Я сделаю с родом Ахава то же самое, что сделал с родом Иеровоама, сына Невата, и с родом Баши, сына Ахии .","10":"А Иезавель собаки сожрут на поле близ Изрееля, и никто не похоронит ее!» Сказав это, он распахнул дверь и бросился прочь.","11":"Когда Иегу вышел к приближенным своего господина, те спросили его: «Все в порядке? Зачем приходил к тебе этот одержимый?» – «Да вы сами знаете, что это за человек, – ответил Иегу, – и что он мог наговорить…» –","12":"«Ты что-то скрываешь! – настаивали те. – Расскажи!» И тогда Иегу передал им слова юноши – пророка: «Он сказал: „Так говорит Господь: этим помазанием Я возвожу тебя в цари Израиля\"».","13":"Присутствовавшие немедленно сорвали с себя одежды и бросили под ноги Иегу – прямо на ступени, где он стоял. Затрубили в рог и возвестили: «Иегу стал царем!»","14":"Так Иегу, сын Иосафата, из рода Нимши, поднял мятеж против Иорама. Все израильское войско, находившееся под командованием Иора – ма, стояло тогда у Рамота Галаадско – го, сдерживало натиск арамейского царя Хазаэла.","15":"Сам же Иорам отъехал в Изреель, залечивать раны, которые ему нанесли арамеи во время сражения с Хазаэлом. Иегу сказал: «Если вы за меня, то пусть ни одна живая душа не посмеет выйти из города и рассказать в Изрееле, что тут происходит!»","16":"А сам взошел на колесницу и поехал в Изреель. Там лежал раненый Иорам, и туда же, чтобы навестить его, прибыл царь Иудеи Ахазия.","17":"Дозорный, что стоял на башне в Изрееле, увидел надвигающиеся войска Иегу и доложил: «Войска идут!» – «Отрядите верхового им навстречу, – распорядился Иорам, – пусть спросит, как у них дела, все ли в порядке».","18":"Всадник подъехал к Иегу и сказал: «Царь спрашивает: как у вас дела? Все в порядке?» Иегу ответил: «Какое тебе дело? Поворачивай и следуй за мной!» Дозорный на башне доложил: «Вестовой подъехал к ним, но не возвращается!»","19":"Послали второго всадника. Он подъехал к войскам и сказал: «Царь спрашивает: как у вас дела? Все в порядке?» Иегу ответил: «Какое тебе дело? Поворачивай и следуй за мной!»","20":"Дозорный доложил: «Вестовой подъехал к ним, но не возвращается… А тот несется – похоже на Иегу, сына Нимши: несется как одержимый!» –","21":"«Запрягайте!» – велел Иорам. Запрягли колесницу. Иорам, царь Израиля, и Ахазия, царь Иудеи, выехали на своих колесницах навстречу Иегу и встретились с ним на том самом участке земли, который принадлежал Навоту из Изрееля.","22":"«Как дела, Иегу? Все в порядке?» – спросил Иорам, увидев его. «Какие могут быть дела, пока кругом блуд и колдовство Иезавели, матери твоей?!» – ответил ему Иегу.","23":"Иорам повернул колесницу и помчался прочь. «Измена, Ахазия!» – крикнул он.","24":"Иегу выстрелил из лука. Стрела вонзилась Иораму между лопаток и пробила сердце. Тело его повисло на колеснице.","25":"Иегу сказал Бидкару, начальнику стражи: «Возьми его труп и брось на участок Навота из Изрееля! Помнишь, мы ехали с тобой бок о бок, сопровождая его отца Ахава, и Господь изрек о нем пророчество:","26":"„Кровь Навота и его сыновей Я видел вчера!\" – сказал Господь. „И на этом же месте Мое возмездие настигнет тебя!\" – сказал Господь. Так возьми его труп и брось на этом участке – пусть исполнится слово Господа».","27":"Ахазия, царь Иудеи, видя, что происходит, помчался прочь, по дороге на Бет – Хагган. Иегу погнался за ним, крича: «Убейте и этого!» Ахазию подстрелили на его колеснице, когда он достиг подъема Гур, что близ Ивлеама. Он добрался до Мегиддо и там умер.","28":"Слуги отвезли тело Ахазии в Иерусалим и похоронили в его гробнице, рядом с предками, в Городе Давидовом.","29":"(Ахазия стал царем Иудеи в одиннадцатый год царствования Иорама, сына Ахава.)","30":"А Иегу вступил в Изреель. Когда Иезавель услышала о случившемся, она подвела глаза сурьмою, красиво убрала волосы и встала у окна.","31":"Иегу как раз въезжал в ворота. «Как дела у Зимри, убийцы своего господина?» – прокричала она ему.","32":"Иегу поднял голову к окну и спросил: «Кто здесь за меня? Есть кто-нибудь?» Из окон выглянули два – три евнуха.","33":"«Сбросьте ее вниз!» – приказал Иегу. Ее сбросили вниз. Кровь брызнула на стену и на коней. Иегу проехал по ее телу.","34":"Войдя во дворец, он сел пировать, но потом распорядился: «Позаботьтесь об этой проклятой, похороните ее – все-таки она царская дочь!»","35":"Пошли хоронить ее, но нашли только череп, ступни и кисти рук.","36":"Вернулись, доложили Иегу. Он сказал: «Вот и сбылось слово Господа, возвещенное его рабом Илией Тишбийским: „На поле близ Изрееля собаки сожрут Иезавель!","37":"Как навоз по пашне – так останки ее на поле под Изреелем разбросаны! Никто и не скажет, что это – Иезавель!\"»"},"10":{"1":"У Ахава в Самарии было семьдесят сыновей. Иегу послал письма в Самарию, военачальникам, старейшинам и опекунам, которых назначил Ахав. Он писал:","2":"«…С вами сыновья вашего господина, у вас есть и колесницы, и конница, и укрепленный город, и оружие. Как получите это письмо,","3":"выбирайте из сыновей вашего господина самого лучшего и достойного, возводите его на отцовский трон – и сражайтесь за род своего господина!»","4":"Тех охватил ужас: «Два царя не смогли ему противостоять. А мы разве сможем?»","5":"Царский управляющий, градоправитель, старейшины и опекуны послали Иегу такой ответ: «Мы – твои рабы, сделаем, что ты скажешь. Мы не будем никого делать царем. Поступай, как тебе угодно».","6":"Тогда Иегу послал им второе письмо: «Если вы за меня и готовы меня слушаться – завтра, в этот же час вы придете ко мне в Изреель и принесете сюда головы сыновей вашего господина!» Царевичей было семьдесят человек. Их воспитывали знатнейшие люди города.","7":"Получив это письмо, они зарезали всех царевичей – семьдесят человек – а головы их положили в корзины и отослали к Иегу в Изреель.","8":"Вестник доложил Иегу: «Принесли головы царевичей». Тот ответил: «Сложите в две кучи у городских ворот; пусть лежат до утра».","9":"Утром Иегу вышел и обратился к народу: «Вы, значит, невиновны? Это я поднял мятеж против моего господина и убил его? Ну, а этих всех – кто их убил?","10":"Знайте: что сказал Господь – то и сбудется. Господь изрек приговор дому Ахава – Господь и сделал все, что было возвещено Его рабом, Илией».","11":"Иегу перебил всех людей из рода Ахава, кого нашел в Изрееле, – и вельмож его, и приближенных, и священников, всех до последнего человека.","12":"Потом Иегу направился в Самарию. По дороге, около Бет – Экед – Хароима,","13":"встретились ему родичи Ахазии, царя Иудеи. Он спросил их: «Кто вы?» Те отвечали: «Мы родичи Ахазии; идем навестить сыновей царя и сыновей царицы – матери». –","14":"«Взять их живьем!» – распорядился Иегу. Их взяли, а потом зарезали в яме для воды, что близ Бет – Экеда. Их было сорок два человека, ни одного из них Иегу не оставил в живых.","15":"Немного дальше он повстречал Ионадава, сына Рехава, и приветствовав его, сказал: «Я с тобой. А ты?» – «Я с тобой!» – отвечал Ионадав. «Если так – дай руку!» Тот подал ему руку. Иегу дал Ионадаву взойти на колесницу","16":"и сказал: «Поедем со мной, увидишь, как ревностно я служу Господу». Ионадав поехал вместе с ним.","17":"Прибыв в Самарию, Иегу перебил всех людей из рода Ахава, кто был в Самарии. Он уничтожил их всех до единого. Так исполнилось слово Господа, возвещенное через Илию.","18":"Собрав народ, Иегу сказал: «Ахав слишком мало служил Ваалу. Иегу будет служить ему гораздо усерднее.","19":"Созовите всех пророков Ваала, всех его поклонников и жрецов – пусть явятся все до единого. Я совершаю большое жертвоприношение Ваалу. Кто не явится, тому не сносить головы». (На самом деле Иегу притворялся – он хотел истребить всех, кто поклонялся Ваалу.) –","20":"«Провозгласите священное собрание, праздник Ваала», – распорядился Иегу. Об этом было объявлено.","21":"Иегу разослал гонцов по всему Израилю, и пришли все, кто поклонялся Ваалу. Все до единого собрались они в храм Ваала; храм наполнился до отказа.","22":"Иегу велел хранителю одеяний: «Выдай одеяния поклонникам Ваала». Тот выдал им одеяния.","23":"Иегу и Ионадав из рода Рехава вошли в храм Ваала, и Иегу сказал поклонникам Ваала: «Посмотрите, проверьте, нет ли здесь кого-нибудь из тех, кто поклоняется Господу, – должны остаться лишь те, кто поклоняется Ваалу».","24":"Потом он приступил к принесению жертв и всесожжении. (А снаружи Иегу поставил восемьдесят воинов и сказал им: «Я привел этих людей прямо вам в руки. За каждого, кто ускользнет, поплатитесь головой».)","25":"Совершив всесожжение, Иегу приказал своим стрелкам и телохранителям: «Войдите внутрь и всех перебейте! Чтобы ни один не ушел живым!» Они перебили всех, кто был внутри, и выбросили их трупы на землю. Потом ворвались в здания, окружавшие храм Ваала,","26":"вынесли из храма Ваала священные камни и сожгли их.","27":"И священный камень Ваала они уничтожили, и сам храм Ваала. А там, где этот храм стоял, устроили отхожее место. Оно там и по сей день.","28":"Так Иегу покончил с Ваалом в Израиле.","29":"Но не отвратился он от грехов, в которые вверг израильтян Иеровоам, сын Невата, – от этих золотых тельцов, что в Бет – Эле и в Дане.","30":"Господь сказал Иегу: «За то, что ты поступал так, как Мне угодно, за то, что сделал с родом Ахава все, что Я хотел, твои потомки – вплоть до праправнуков твоих – будут восседать на престоле Израиля!»","31":"Но не стал Иегу всем сердцем следовать Закону Господа, Бога Израилева – не отвратился он от тех грехов, в которые вверг израильтян Иеровоам, сын Невата.","32":"В ту пору Господь впервые отторг от Израиля часть страны. Хазаэл завоевал все израильские владения","33":"на восток от Иордана: весь Галаад; землю Гада, Рувима и Манассии, вплоть до Ароэра, что над Арнонским ущельем; и Галаад, и Башан.","34":"Прочее о деяниях Иегу и о его доблести написано в «Летописях царей Израиля».","35":"Упокоился Иегу рядом со своими предками, и похоронили его в Самарии. Царем после него стал его сын Иоахаз.","36":"Иегу, царь Израиля, царствовал в Самарии двадцать восемь лет."},"11":{"1":"Когда Гофолия, мать Ахазии, узнала о смерти сына, она перебила всех наследников престола.","2":"Но Иехошева, дочь царя Иорама и сестра Ахазии, похитила Иоаса, сына Ахазии, и не дала убить его вместе с другими царевичами – спрятала его в спальне, вместе с его кормилицей. Так, благодаря Иехошеве, Иоас был спрятан от Гофолии и избежал смерти.","3":"Шесть лет его вместе с кормилицей скрывали в Храме Господа. Страной в это время правила Гофолия.","4":"На седьмой год Иехояда велел карянским сотникам и сотникам стрелков собраться к нему, в Храм Господа. Он привел их к присяге, заставив дать клятву в Храме Господа, показал им царевича","5":"и отдал приказ: «Вот что вы должны делать. Пусть треть из тех, кто заступает в эту субботу на службу, несет охрану дворца,","6":"треть – пусть станет у ворот Сур, и треть – у ворот Стрелков; вам надлежит охранять дворец.","7":"А другие два отряда – те, кто не должен в эту субботу заступать на службу, – пусть будут у Храма Господа; вам надлежит охранять царя.","8":"Станьте вокруг царя с оружием в руках. Всякий, кто направится к Рядам, будет убит. Повсюду следуйте за царем».","9":"Сотники исполнили все, что приказал им священник Иехояда. Все они – и те, кто в ту субботу заступал на службу, и те, кто не заступал, – пришли к священнику Иехояде, каждый со своей сотней,","10":"а священник Иехояда выдал им копья и колчаны царя Давида, хранившиеся в Храме Господа.","11":"Стрелки, с оружием в руках, встали от южного крыла Храма до северного, а также у жертвенника и перед Храмом, чтобы охранять царя со всех сторон.","12":"Иехояда вывел царевича, возложил на него корону и вручил ему знаки царского достоинства. Иоаса провозгласили царем, помазали его на царство, и рукоплеща, стали кричать: «Да здравствует царь!»","13":"Услышав шум собравшегося народа и стрелков, Гофолия вышла к собравшимся, к Храму Господа, –","14":"и видит, что на помосте, как положено по обычаю, стоит царь, рядом с царем стоят военачальники, трубачи с трубами, а народ ликует и трубит в трубы. И тогда, разодрав одежды, закричала Гофолия: «Измена, измена!»","15":"Священник Иехояда приказал сотникам, которые командовали отрядами: «Выведите ее из Храма, к Рядам. Кто будет на ее стороне – убивайте». (Он подумал, что нельзя убивать ее прямо в Храме Господа.)","16":"Гофолию схватили, через Конские ворота отвели во дворец и там убили.","17":"Священник Иехояда привел царя и народ к присяге на верность Господу – чтобы народ этот был народом Господа – а народ он привел к присяге на верность царю.","18":"Потом весь народ пошел к храму Ваала и разрушил его. Жертвенники и статуи разбили, а Маттана, Ваалова жреца, убили прямо перед жертвенниками. Оставив охрану при Храме Господа,","19":"Иехояда, в сопровождении сотников, карян, стрелков и всего народа, вывел царя из Храма Господа и через ворота Стрелков ввел во дворец. Иоас воссел на царский трон.","20":"Народ ликовал, в городе воцарилось спокойствие. Гофолию убили во дворце.","21":"Семь лет было Иоасу, когда он стал царем."},"12":{"1":"На седьмой год царствования Иегу царем Иудеи стал Иоас; он царствовал в Иерусалиме сорок лет. Его мать – Цивья, родом из Беэр – Шевы.","2":"До конца дней своих Иоас творил дела, угодные Господу, следуя наставлениям священника Иехояды.","3":"Но капища так и не были упразднены, и в этих капищах народ по – прежнему закалывал и сжигал жертвы.","4":"Иоас сказал священникам: «Все деньги, которые поступают в Храм Господа, для святыни: деньги от подушной подати, деньги, принесенные как выкуп, а также все добровольные пожертвования Храму Господа –","5":"пусть священники забирают эти деньги у своих помощников и на эти деньги ремонтируют Храм, где потребуется».","6":"Но к двадцать третьему году царствования царя Иоаса священники так и не справились с ремонтом Храма.","7":"Царь Иоас вызвал священника Иехояду и остальных священников. «Почему вы не занимаетесь ремонтом Храма? – спросил он их. – Раз так, не берите больше денег у своих помощников, пусть эти деньги идут на ремонт Храма».","8":"Священники обещали, что сами они больше денег собирать не будут и отстранятся от ремонта Храма.","9":"Священник Иехояда взял ящик и, проделав в крышке отверстие, поставил его справа от жертвенника. В этот ящик священники стражи ворот стали опускать деньги, которые приносили люди, приходившие в Храм Господа.","10":"Когда видели, что в ящике уже набралось достаточно денег, то приходил царский писец, вместе с верховным священником, и пересчитав деньги, поступившие в Храм Господа, перекладывали их в мешок.","11":"Пересчитанные деньги они передавали тем, кто был назначен вести работы в Храме Господа, оплачивали работу плотников, строителей,","12":"каменщиков, каменотесов, а также покупку дерева и тесаного камня, которые требовались для ремонта Храма, – словом, оплачивали все, что требовалось для ремонта.","13":"Деньги, поступавшие в Храм Господа, не расходовались ни на серебряные чаши, ни на щипцы, ни на кропильницы, ни на трубы, ни на золотую или серебряную утварь:","14":"все шло тем, кто работал в Храме, на ремонт Храма.","15":"А с тех, кому передавали эти деньги, чтобы рассчитаться с рабочими, отчета не требовали: им доверяли.","16":"(Однако деньги, принесенные на возместительную или очистительную жертву, шли не в Храм, а священникам.)","17":"В ту пору Хазаэл, царь Арама, пошел войной на Гат и захватил его. После этого он задумал идти на Иерусалим.","18":"Тогда Иоас, царь Иудеи, взял все, что было посвящено в Храм его предками Иосафатом, Иорамом и Ахазией, царями Иудеи, а также все, что он сам посвятил в Храм, и еще все золото, какое нашлось в сокровищнице Храма Господа и в дворцовой сокровищнице, – и послал Хазаэлу. И Хазаэл отступил от Иерусалима.","19":"Прочее о деяниях Иоаса написано в «Летописях царей Иудеи».","20":"Приближенные Иоаса составили против него заговор и убили его в Бет – Милло. (По дороге в Милло","21":"на него напали Иозахар, сын Шимата, и Иозавад, сын Шомера, приближенные царя, и убили его.) Он был похоронен рядом с предками в Городе Давидовом. Царем после него стал Амасия, его сын."},"13":{"1":"На двадцать третий год царствования Иоаса, сына Ахазии, царя Иудеи, царем Израиля стал Иоахаз, сын Иегу. Он царствовал в Самарии семнадцать лет.","2":"Он творил дела, ненавистные Господу, – он продолжал творить грехи, в которые вверг израильтян Иеровоам, сын Невата; не отвратился Иоахаз от этих грехов.","3":"Господь прогневался на Израиль – и надолго отдал израильтян в руки Хазаэла, царя арамейского, а также Бен – Хадада, сына Хазаэла.","4":"(Когда Иоахаз взмолился к Господу, Господь внял его молитве. Увидел Господь, какая беда постигла Израиль – как притесняет его царь Арама –","5":"и послал Израилю избавителя. Израильтяне освободились от гнета арамеев и стали жить в своей стране спокойно, как прежде.","6":"Однако и тогда они не отвратились от тех грехов, в которые род Иеровоама вверг Израиль, продолжали поступать, как прежде поступали. Стояло и древо Ашеры в Самарии.)","7":"Войска у Иоахаза почти что не осталось: только пятьдесят всадников, десять колесниц и десять тысяч пеших. Царь Арама громил израильтян, топтал их как дорожную пыль.","8":"Прочее о деяниях Иоахаза и его доблести написано в «Летописях царей Израиля».","9":"И упокоился Иоахаз рядом со своими предками – был похоронен в Самарии. Царем после него стал его сын Иоас.","10":"На тридцать седьмой год царствования Иоаса, царя Иудеи, царем Израиля стал Иоас, сын Иоахаза. Он царствовал в Самарии шестнадцать лет.","11":"Он творил дела, ненавистные Господу. Он не отвратился от тех грехов, в которые вверг израильтян Иеровоам, сын Невата; продолжал Иоас творить эти грехи.","12":"Прочее о деяниях Иоаса и его доблести (и о том, как воевал он с Амасией, царем Иудеи) написано в «Летописях царей Израиля».","13":"И упокоился Иоас рядом со своими предками, а на престол взошел Иеровоам. Иоас был похоронен в Самарии, рядом с другими царями Израиля.","14":"Когда Елисей занемог и был при смерти, к нему пришел Иоас, царь Израиля, и стал плакать над ним: «Отец мой, отец мой! Колесницы и кони Израилевы!»","15":"Тогда Елисей сказал ему: «Возьми лук и стрелы». Тот взял лук и стрелы.","16":"«Положи руку на тетиву», – сказал Елисей. Тот положил. Елисей возложил свои руки на руки царя","17":"и сказал: «Открой окно на восточную сторону». Тот открыл. «Стреляй!» – сказал Елисей. Тот выстрелил. И сказал Елисей: «Стрела Господней победы! Стрела побед над Арамом! В Афеке ты разгромишь арамеев – всех до единого!»","18":"Потом сказал царю Израиля: «Бери стрелы». Тот взял. «Бей оземь!» – сказал Елисей. Тот ударил ими оземь три раза и остановился.","19":"Рассердился человек Божий и сказал ему: «Если бы ты ударил пять – шесть раз, то уничтожил бы всех арамеев, до единого. А так – только три раза побьешь арамеев».","20":"Елисей умер, и его похоронили. В тот год моавитяне устроили набег на Израиль.","21":"Когда хоронили одного человека, вдруг показался отряд моавитян. Люди бросили тело в гробницу Елисея и убежали. А покойник, соприкоснувшись с костями Елисея, ожил и встал.","22":"Хазаэл, царь Арама, притеснял Израиль все время правления Иоахаза.","23":"Но Господь пожалел израильтян, помиловал и простил их, ради того договора о верности, который Он заключил с Авраамом, Исааком и Иаковом. Он решил не губить их – в ту пору Он еще не отверг их и не отвернулся от них!","24":"Умер Хазаэл, царь Арама, и царем после него стал его сын Бен – Хадад.","25":"Тогда Иоас, сын Иоахаза, отвоевал у Бен – Хадада, сына Хазаэла, те города, что некогда Хазаэл захватил у Иоахаза. Иоас трижды разбил арамеев и вернул израильские города."},"14":{"1":"На второй год царствования Иоаса, сына Иоахаза, царя израильского, царем Иудеи стал Амасия, сын Иоаса.","2":"Когда Амасия стал царем, ему было двадцать пять лет. Он царствовал в Иерусалиме двадцать девять лет. Его мать – Иоаддан, родом из Иерусалима.","3":"Деяния Амасии были угодны Господу, но все же не настолько, насколько деяния Давида, его прародителя. Он во всем поступал так же, как его отец Иоас.","4":"Капища так и не были упразднены, и в этих капищах народ по – прежнему закалывал и сжигал жертвы.","5":"Когда Амасия крепко взял власть в свои руки, он казнил тех вельмож, что убили его отца, царя.","6":"Но сыновей убийц он не казнил, ведь в Законе Моисея написано, что Господь заповедал: «Отцов нельзя предавать смерти за вину сыновей, а сыновей – за вину отцов. Человек может быть предан смерти лишь за то преступление, которое совершил он сам».","7":"Амасия разгромил десять тысяч эдомитян в Соляной долине. Он отвоевал у них Селу и переименовал ее в Иоктеэл (так называется этот город и по сей день).","8":"После этого Амасия отправил посланцев к Иоасу, сыну Иоахаза, сына Иегу, царю Израиля, и велел передать ему: «Приходи. Сойдемся лицом к лицу!»","9":"Иоас, царь Израиля, велел ответить Амасии, царю Иудеи: «Как-то раз ливанский чертополох отправил посланцев к ливанскому кедру: „Выдавай, – говорит, – свою дочь замуж за моего сына\". Шел мимо зверь ливанский – и растоптал этот чертополох.","10":"Победа над Эдомом вскружила тебе голову. Гордиться гордись – да только сидя дома. Зачем накликаешь на себя беду? И сам падешь, и вместе с тобой – Иудея».","11":"Но не послушал его Амасия. Пришел Иоас, царь Израиля, – и сошлись они с Амасией лицом к лицу в Бет – Шемеше, что в Иудее.","12":"Иудеи были разбиты израильтянами и разбежались по домам.","13":"А сам Амасия, царь Иудеи, сын Иоаса, сына Ахазии, попал при Бет – Шемеше в плен к Иоасу, царю Израиля. Иоас подступил к Иерусалиму, сделал в стене пролом длиною в четыреста локтей, от Ефремовых ворот до Угловых, и вошел в город.","14":"Он забрал все золото и серебро, всю утварь, какая нашлась в Храме Господа и в дворцовой сокровищнице, взял заложников и вернулся в Самарию.","15":"Прочее о деяниях Иоаса и его доблести, и о том, как он воевал с Амасией, царем Иудеи, написано в «Летописях царей Израиля».","16":"И упокоился Иоас рядом со своими предками – был похоронен в Самарии, с царями Израиля. Царем после него стал его сын Иеровоам.","17":"Амасия, сын Иоаса, царь Иудеи, пережил Иоаса, сына Иоахаза, царя израильского, на пятнадцать лет.","18":"Прочее об Амасии написано в «Летописях царей Иудеи».","19":"Против него в Иерусалиме составили заговор. Амасия бежал в Лахиш, но заговорщики послали за ним в Лахиш своих людей и убили его.","20":"Тело увезли из Лахиша на лошадях, и Амасия был похоронен вместе с предками в Городе Давидовом.","21":"А царем, вместо Амасии, весь народ Иудеи сделал его сына, шестнадцатилетнего Азарию.","22":"(Того самого, который вновь отстроил Элат и вернул его под власть Иудеи.) Произошло это после того, как прежний царь упокоился рядом со своими предками.","23":"На пятнадцатый год царствования Амасии, сына Иоаса, царя Иудеи, царем Израиля стал Иеровоам, сын Иоаса. Он царствовал в Самарии сорок один год.","24":"Он творил дела, ненавистные Господу, – не отвратился он от тех грехов, в которые вверг израильтян Иеровоам, сын Невата.","25":"Он вернул под власть Израиля все земли от Лево Хаматского до Мертвого моря. Так исполнилось слово Господа, Бога Израиля, которое возвестил Его раб, пророк Иона, сын Амиттая, из Гат – Хефера.","26":"Увидел Господь, что Израиль бедствует, что гибнут все, от мала до велика, что нет для Израиля избавителя, –","27":"и не захотел Господь, чтобы имя Израиля было стерто под небесами. Руками Иеровоама, сына Иоаса, Господь спас израильтян.","28":"Прочее о деяниях Иеровоама и его доблести, и о войнах, которые он вел, и о том, как он вернул Дамаск и Хамат под власть Иудеи с Израилем, написано в «Летописях царей Израиля».","29":"И упокоился Иеровоам рядом со своими предками, царями Израиля. Царем после него стал его сын Захария."},"15":{"1":"На двадцать седьмой год царствования Иеровоама, царя израильского, царем Иудеи стал Азария, сын Амасии.","2":"Когда Азария стал царем, ему было шестнадцать лет. Он царствовал в Иерусалиме пятьдесят два года. Его мать – Иехолия, родом из Иерусалима.","3":"Его деяния были угодны Господу, он во всем поступал так же, как его отец Амасия.","4":"Но капища так и не были упразднены, и в этих капищах народ по – прежнему закалывал и сжигал жертвы.","5":"Господь поразил царя болезнью: Азария до самой смерти был болен проказой и жил в Бет – ха – Хофшит, а царевич Иофам вел государственные дела, правил народом страны.","6":"Прочее о деяниях Азарии написано в «Летописях царей Иудеи».","7":"И упокоился Азария рядом со своими предками – похоронили его вместе с предками в Городе Давидовом. Царем после него стал его сын Иофам.","8":"На тридцать восьмой год царствования Азарии, царя Иудеи, царем Израиля стал Захария, сын Иеровоама. Он царствовал в Самарии шесть месяцев.","9":"Его дела были так же ненавистны Господу, как и дела его предков – не отвратился он от тех грехов, в которые вверг израильтян Иеровоам, сын Невата.","10":"Шаллум, сын Явеша, составил против него заговор, убил его в Ивлеаме и сам стал царем.","11":"Прочее о деяниях Захарии написано в «Летописях царей Израиля».","12":"Сбылось слово Господа, которое Он возвестил Иегу: «Твой сын, внук, правнук и праправнук будут сидеть на израильском престоле». Так и было.","13":"На тридцать девятый год царствования Озии, царя Иудеи, царем стал Шаллум, сын Явеша. Он царствовал в Самарии один месяц.","14":"Менахем, сын Гади, пошел из Тирцы на Самарию. Там, в Самарии, он убил Шаллума, сына Явеша, и сам стал царем.","15":"Прочее о Шаллуме и его заговоре написано в «Летописях царей Израиля».","16":"Менахем уничтожил Таппуах и всех его жителей и разорил все его окрестности, вплоть до Тирцы, – за то, что ему не открыли ворота. Он убил всех беременных женщин, что были в городе, вспорол им животы.","17":"На тридцать девятый год царствования Азарии, царя Иудеи, царем Израиля стал Менахем, сын Гади. Он царствовал в Самарии десять лет.","18":"Он творил дела, ненавистные Господу – не отвратился он от тех грехов, в которые вверг израильтян Иеровоам, сын Невата.","19":"В его правление в страну вторгся Пул, царь Ассирии. Менахем заплатил Пулу тысячу талантов серебра, чтобы Пул взял его под свое покровительство и помог удержать царскую власть.","20":"Эту дань Менахем разложил на всех израильтян – на всех, у кого был хоть какой-то достаток. Каждый должен был дать по пятьдесят шекелей серебра для царя Ассирии. После этого царь Ассирии ушел из страны.","21":"Прочее о деяниях Менахема написано в «Летописях царей Израиля».","22":"И упокоился Менахем рядом со своими предками. Царем после него стал его сын Пекахия.","23":"На пятидесятый год царствования Азарии, царя Иудеи, царем Израиля стал Пекахия, сын Менахема. Он царствовал в Самарии два года.","24":"Он творил дела, ненавистные Господу, – не отвратился он от тех грехов, в которые вверг израильтян Иеровоам, сын Невата.","25":"Пеках, сын Ремами, начальник стражи, составил против него заговор и убил его в Самарии, в покоях дворца. С ним было пятьдесят галаадцев. Убив Пекахию, Пеках сам стал царем.","26":"Прочее о деяниях Пекахии написано в «Летописях царей Израиля».","27":"На пятьдесят второй год царствования Азарии, царя Иудеи, царем Израиля стал Пеках, сын Ремалии. Он царствовал в Самарии двадцать лет.","28":"Он творил дела, ненавистные Господу, – не отвратился он от тех грехов, в которые вверг израильтян Иеровоам, сын Невата.","29":"При Пекахе, царе Израиля, пришел Тиглатпаласар, царь Ассирии, и захватил Ийон, Авел, что в Бет – Маахе, Яноах, Кедеш, Хацор, и Галаад, и Галилею, и всю землю Неффалима. Жителей этих мест он угнал в Ассирию.","30":"Осия, сын Элы, составил заговор против Пекаха, сына Ремалии, и убил его. Убив Пекаха, Осия стал царем вместо него, на двадцатый год царствования Иофама, сына Озии.","31":"Прочее о деяниях Пекаха написано в «Летописях царей Израиля».","32":"На второй год царствования Пекаха, сына Ремалии, царя израильского, царем Иудеи стал Иофам, сын Озии.","33":"Когда Иофам стал царем, ему было двадцать пять лет. Он царствовал в Иерусалиме шестнадцать лет. Его мать – Иеруша, дочь Цадока.","34":"Его деяния были угодны Господу, он во всем поступал так же, как его отец Озия.","35":"Но капища так и не были упразднены, и в этих капищах народ по – прежнему закалывал и сжигал жертвы. Он построил Верхние ворота Храма Господа.","36":"Прочее о деяниях Иофама написано в «Летописях царей Иудеи».","37":"При нем Господь впервые наслал на Иудею Рецина, царя Арама, и Пекаха, сына Ремалии.","38":"И упокоился Иофам рядом со своими предками – был похоронен рядом с предками в Городе Давидовом. Царем после него стал его сын Ахаз."},"16":{"1":"На семнадцатый год царствования Пекаха, сына Ремалии, царем Иудеи стал Ахаз, сын Иофама.","2":"Когда Ахаз стал царем, ему было двадцать лет. Он царствовал в Иерусалиме шестнадцать лет. Не творил он дел, угодных Господу, его Богу, не брал пример со своего предка Давида,","3":"а шел путем царей Израиля. Он даже сына своего принес в огненную жертву – подобные мерзости делали народы, которые Господь истребил, чтобы отдать их землю Израилю.","4":"И в капищах, и на холмах, и под каждым деревом ветвистым он закалывал и сжигал жертвы.","5":"В то время на Иудею пошли войной Рецин, царь Арама, и Пеках, сын Ремалии, царь Израиля. Они осадили Ахаза в Иерусалиме, но не смогли одолеть его.","6":"(Тогда же Рецин, царь Арама, вернул Элат под власть Арама и изгнал оттуда иудеев. Арамеи пришли в Элат и поселились там; они и до сих пор там живут).","7":"Ахаз отправил послов к Тиглатпаласару, царю Ассирии, и велел передать ему: «Я твой раб и твой сын! Приди, спаси меня от врагов моих: царя арамейского и царя израильского».","8":"Ахаз взял серебро и золото, какое было в Храме Господа и в дворцовой сокровищнице, и послал подношение царю Ассирии.","9":"Царь Ассирии внял его просьбе. Он подступил к Дамаску, взял его, жителей угнал в Кир, а Рецина казнил.","10":"Царь Ахаз отправился в Дамаск, чтобы предстать там пред Тиглатпаласаром, царем Ассирии. Увидев дамасский жертвенник, он послал священнику Урии изображение этого жертвенника – подробный чертеж.","11":"К возвращению царя священник Урия уже соорудил новый жертвенник, в точности такой, как изображение, присланное царем Ахазом из Дамаска.","12":"Когда царь вернулся из Дамаска, он осмотрел жертвенник, подошел к нему, поднялся,","13":"сжег на нем жертву всесожжения, сжег приношение, совершил на нем возлияние и окропил его кровью пиршественной жертвы.","14":"А медный жертвенник, что был пред лицом Господа, царь велел передвинуть от входа в Храм, чтобы не стоял он между новым жертвенником и Храмом, и поставить по северную сторону от нового жертвенника.","15":"Царь Ахаз велел священнику Урии: «На большом жертвеннике сжигай утренние всесожжения и вечерние приношения – жертвы, приносимые царем, и жертвы, приносимые всем народом. Возливай на него возлияния, кропи кровью всех всесожжении и жертв. А медный жертвенник будет у меня для гадания по внутренностям».","16":"Священник Урия сделал все, как повелел ему царь Ахаз.","17":"Царь Ахаз велел снять с подставок облицовку панелей, снять чаны с подставок, спустить Медное Море с медных быков, которые его подпирали, прямо на каменный пол,","18":"а также снять облицовку с балдахина над троном, стоявшим в Храме, и с внешней царской галереи, что шла вокруг Храма Господнего. (Все это было сделано из-за царя ассирийского.)","19":"Прочее о деяниях Ахаза написано в «Летописях царей Иудеи».","20":"И упокоился Ахаз рядом со своими предками – был похоронен рядом с предками в Городе Давидовом. Царем после него стал его сын Езекия."},"17":{"1":"На двенадцатый год царствования Ахаза, царя Иудеи, царем Израиля стал Осия, сын Элы. Он царствовал в Самарии девять лет.","2":"Его дела были ненавистны Господу, хотя и не настолько, как дела других царей Израиля, его предшественников.","3":"Салманасар, царь Ассирии, пошел на Осию войной. Осия стал подвластен ему и начал платить ему дань.","4":"Но потом царь Ассирии обвинил Осию в измене, за то что тот отправил посольство к Со, царю Египта, и не выплатил дань, которую должен был ежегодно платить царю Ассирии. Царь Ассирии схватил Осию и заключил в тюрьму.","5":"Царь Ассирии занял всю страну, подступил к Самарии и три года держал ее в осаде.","6":"На девятый год царствования Осии царь Ассирии взял Самарию, угнал израильтян в Ассирию и поселил их в Халахе и на реке Хабур, что течет через Гозан, а также в городах Мидии.","7":"Виновны были израильтяне перед Господом, своим Богом, который вывел их из Египта, из-под власти фараона, царя египетского. Они чтили других богов,","8":"они следовали обычаям народов, землю которых Господь им отдал, а также обычаям, которые установили цари Израильские.","9":"Они грешили бесчестными поступками против Господа, своего Бога. Они строили капища во всех своих селениях, от сторожевой крепости до большого укрепленного города,","10":"ставили священные камни и Ашеры на каждом высоком холме и под каждым деревом ветвистым","11":"и там, в капищах, сжигали жертвы – подобно народам, которых Господь угнал из этой земли, чтобы отдать ее израильтянам. Они оскорбляли Господа своими злыми делами.","12":"Они поклонялись идолам, хотя Господь велел им этого не делать.","13":"Господь предупреждал израильтян и иудеев устами всех своих пророков и провидцев: «Вернитесь, сойдите с дурного пути! Соблюдайте Мои заповеди и установления – они изложены в Законе, который Я дал вашим отцам и который Я послал вам через пророков, рабов Моих!»","14":"Но они не слушали. Они были так же упрямы, как и отцы их, которые не верили Господу, своему Богу.","15":"И законы Его, и договор о верности, который Он заключил с их отцами, и повеления, которые Он им заповедал, они не ставили ни во что. Они стали поклоняться пустому – вот и осталось от них пустое место. Они подражали окрестным народам, несмотря на то, что Господь велел им не брать с них примера.","16":"Они пренебрегали всеми повелениями Господа, своего Бога. Они сделали себе двух литых тельцов; поставили древо Ашеры, поклонялись всему воинству небесному, служили Ваалу.","17":"Сыновей и дочерей приносили в огненные жертвы; занимались колдовством и гадали. Они погрязли в грехе, в делах, ненавистных Господу.","18":"За все это разгневался Господь на племя Израиля, отверг его и отвернулся от него – одно только племя Иуды осталось.","19":"Но и племя Иуды тоже не исполняло повелений Господа, своего Бога; оно переняло обычаи, которым следовало племя Израиля…","20":"Опротивел Господу весь род Израиля, и Господь унизил его и предал его на разграбление, отверг его и отвернулся от него!","21":"(Когда Он отторг Израиль от царства Давидова, и израильтяне сделали своим царем Иеровоама, сына Невата, то Иеровоам заставил израильтян забыть Господа – вверг их в страшный грех.","22":"И шли израильтяне путем грехов Иеровоамовых, так и не отвратились от этих грехов.","23":"Шли, пока Господь не отверг израильтян и не отвернулся от них, как Он и предупреждал устами всех пророков, рабов Своих. Израильтяне были переселены из своей страны в Ассирию, где живут и поныне.)","24":"В города и селения Самарии вместо израильтян, царь Ассирии привел людей из Вавилона, из Куты, из Аввы, из Хамата, из Сефарваима. Они сделались хозяевами самарийской страны, стали жить в ее городах и селениях.","25":"Первое время после того, как их там поселили, они не чтили Господа, и Господь наслал на них львов, которые нападали на них и убивали.","26":"Царю Ассирии донесли: «Народы, которые ты переселил в города и селения Самарии, не умеют, как положено, чтить Бога той страны, и этот Бог наслал на них львов. Львы истребляют их, потому что эти люди не умеют, как положено, чтить Бога той страны».","27":"Царь Ассирии повелел: «Верните кого-нибудь из священников, которых вы оттуда угнали, – пусть придет, поселится там и учит эти народы, как положено чтить Бога той страны».","28":"И вернулся туда один из священников, угнанных из Самарии. Он поселился в Бет – Эле и стал учить эти народы, как чтить Господа.","29":"Меж тем каждый народ делал статуи своих богов и ставил в своих селениях, – в храмах – капищах, построенных самаритянами.","30":"Так, вавилоняне воздвигли статую Суккот – Бенот, люди из Куты – Нергала, люди из Хамата – статую Ашимы,","31":"аввеи – Нивхаза и Тартака, а переселенцы из Сефарваима сжигали своих детей в жертву Адраммелеху и Анаммелеху, богам Сефарваима.","32":"Одновременно они поклонялись и Господу. Они делали своих соплеменников жрецами капищ, и те служили в этих храмах – капищах.","33":"И Господу они поклонялись, и богам своим служили – служили так, как было принято у них на родине, там, откуда их переселили.","34":"И доныне поступают они по своим старым обычаям. Не поклоняются они Господу! Не соблюдают ни правил, ни предписаний, ни Закона – ничего, что Господь повелел соблюдать потомкам Иакова, имя которого Он поменял на «Израиль».","35":"А ведь Господь, заключая с ними договор о верности, велел им: «Не чтите иных богов и не поклоняйтесь им, не служите им и не приносите им жертв.","36":"Чтите одного только Господа, который вывел вас из Египта великой Своей силой, рукой Своей простертой. Одному Ему поклоняйтесь, одному Ему приносите жертвы.","37":"Строго соблюдайте и исполняйте установления и предписания, Закон и правила, которые Он написал для вас.","38":"Не забывайте договор, который Я заключил с вами, и не чтите никаких других богов.","39":"Чтите одного только Господа, вашего Бога, – и Он защитит вас от всех врагов».","40":"Не вняли они! Поступают по своим старым обычаям.","41":"И Господу поклоняются, и идолам своим продолжают служить. И доныне их дети и внуки поступают так же, как поступали отцы их."},"18":{"1":"В третий год Осии, сына Элы, царя израильского, царем Иудеи стал Езекия, сын Ахаза.","2":"Когда Езекия стал царем, ему было двадцать пять лет. Он царствовал в Иерусалиме двадцать девять лет. Его мать – Ави, дочь Захарии.","3":"Он творил дела, угодные Господу, совершенно как предок его Давид.","4":"Он упразднил капища, разбил священные камни, срубил древо Ашеры и уничтожил медного змея, которого сделал Моисей (а до тех пор израильтяне сжигали жертвы перед этим змеем; назывался же он Нехуштан).","5":"На Господа, Бога Израилева, уповал Езекия; не было равных ему среди царей Иудеи ни после него, ни прежде.","6":"Он был всецело предан Господу, не отступал от Него, соблюдал все Его повеления, данные через Моисея. Господь был с Езекией: за что бы Езекия ни брался, все удавалось. Езекия восстал против царя Ассирии и вышел из-под его власти.","8":"Езекия разбил филистимлян. Он дошел до самой Газы и ее окрестностей, взял и сторожевые башни, и укрепленные города.","9":"В четвертый год царствования Езекии (то есть в седьмой год царствования Осии, сына Элы, царя израильского) Салманасар, царь Ассирии, пошел на Самарию и осадил ее,","10":"а через три года взял. В шестой год царствования Езекии (то есть в девятый год царствования Осии, сына Элы, царя израильского) пала Самария.","11":"Царь Ассирии угнал израильтян в Ассирию и поселил их в Халахе и на реке Хабур, что течет через Гозан, а также в городах Мидии.","12":"А случилось это потому, что не слушались они Господа, своего Бога, не соблюдали договор о верности, который Он заключил с ними, не соблюдали повеления Моисея, раба Господнего. Не слушали и не соблюдали!","13":"В четырнадцатый год правления царя Езекии Синаххериб, царь ассирийский, осадил и взял все укрепленные города Иудеи.","14":"И отправил Езекия, царь Иудеи, царю Ассирии в Лахиш такое послание: «Виноват я. Отступи от меня. Любую дань, какую наложишь на меня, я выплачу». Царь Ассирии обязал Езекию, царя Иудеи, дать ему триста талантов серебра и тридцать талантов золота.","15":"Езекия отдал все серебро, какое нашлось в Храме Господа и в дворцовой сокровищнице.","16":"Он снял облицовку с дверей Храма Господа и с косяков (облицовка эта была сделана по распоряжению самого Езекии), и отдал все это царю Ассирии.","17":"Царь ассирийский послал из Лахиша в Иерусалим, к царю Езекии, своего главнокомандующего, главного евнуха и главного виночерпия, с большим войском. Пришли они к Иерусалиму, остановились у канала, подводящего воду к Верхнему пруду, близ дороги к полю Белильщика,","18":"и стали вызывать царя. К ним вышли царский управляющий Элиаким, сын Хилкии, писец Шевна и глашатай Иоах, сын Асафа.","19":"Главный виночерпий сказал им: «Передайте Езекии: „Так говорит великий царь, царь ассирийский: на что ты надеешься?","20":"Ты говоришь пустые слова, а для войны нужно иметь разум и силу! Ты восстал против меня – на кого ты понадеялся?","21":"На Египет думаешь опереться, на эту палку надломленную? Кто на такую палку обопрется, тому она вонзится в руку, насквозь проткнет! Таков фараон, царь египетский, для всех, кто на него понадеялся.","22":"Или, может быть, скажете, что вы надеетесь на Господа, вашего Бога? Но не Его ли капища и жертвенники уничтожил Езекия, велев жителям Иудеи и Иерусалима поклоняться лишь здесь, в Иерусалиме, перед этим жертвенником?\"","23":"А вот побейся-ка об заклад с моим господином, царем ассирийским: я дам тебе две тысячи коней – сумеешь набрать для них всадников?","24":"Сможешь ли ты дать отпор хотя бы одному, пусть самому слабому из наместников, которые служат моему господину? На колесницы и конницу Египта надеешься?!..","25":"И потом, разве не по воле Господа я пришел опустошить этот край? „Иди в эту страну и опустоши ее!\" – сказал мне Господь».","26":"Элиаким, сын Хилкии, Шевна и Иоах попросили главного виночерпия: «Говори с нами, рабами твоими, по – арамейски, мы поймем. Не говори по – еврейски, ведь народ на стене все слышит».","27":"Главный виночерпий ответил: «А разве господин мой послал меня передать эти слова тебе и твоему господину? Нет! Всем этим людям на стене, которые вместе с вами обречены есть свои нечистоты и пить свою мочу!»","28":"Тут главный виночерпий поднялся и громко прокричал по – еврейски: «Слушайте слово великого царя, царя ассирийского!","29":"Так говорит царь: пусть не обманывает вас Езекия – не сможет он вас спасти!","30":"И пусть Езекия не внушает вам надежд на Господа, пусть не обещает, что Господь вас спасет и этот город не будет отдан в руки царя ассирийского.","31":"Не слушайте Езекию! Так говорит царь ассирийский: помиритесь со мной и выходите ко мне – каждый из вас будет есть плоды своей лозы и своей смоковницы и пить воду из своего колодца,","32":"а потом я приду и заберу вас в другую страну – такую же, как ваша, – в страну зерна и вина, в страну хлеба и виноградников, страну масла и меда. И вы будете жить, не умрете! И не слушайте Езекию: он обманывает, говоря, что Господь спасет вас.","33":"Разве боги других стран спасли свои страны от царя ассирийского?","34":"Где теперь боги Хамата и Арпада, где боги Сефарваима, Хены, Иввы? А Самарию разве спасли они от меня?","35":"Кто из богов этих стран спас от меня свою страну? И неужели Господь спасет от меня Иерусалим?»","36":"Народ молчал, не отвечал ни слова, ибо таков был приказ царя – не отвечать.","37":"Затем царский управляющий Элиаким, сын Хилкии, писец Шевна и глашатай Иоах, сын Асафа, разорвав на себе одежды, пришли к Езекии и передали ему слова главного виночерпия."},"19":{"1":"Когда царь Езекия услышал все это, он разорвал на себе одежды и, одевшись в дерюгу, пошел в Храм Господа.","2":"А царского управляющего Элиакима, писца Шевну и старших священников он послал, одетыми в дерюгу, к пророку Исайе, сыну Амоца.","3":"И они сказали Исайе: «Так говорит Езекия: настал день скорби, наказания и унижения. Роды начались, да разродиться нет сил!","4":"Но, может быть, Господь, твой Бог, услышит слова главного виночерпия, которого господин его, царь ассирийский, послал оскорблять Бога Живого, – и тогда Господь, твой Бог, покажет, чего стоят эти слова! Помолись за немногих уцелевших».","5":"Когда пришли к Исайе приближенные царя Езекии,","6":"Исайя сказал им: «Передайте вашему господину: „Так говорит Господь: не пугайся слов, которые ты услышал, слов, которыми поносят Меня прислужники царя ассирийского.","7":"Вот, Я насылаю на него дух – царь ассирийский получит весть и вернется в свою страну. Там, в его стране, Я сражу его мечом\"».","8":"И вернулся главный виночерпий к царю ассирийскому, который тогда осаждал Ливну (как стало известно главному виночерпию, царь уже покинул Лахиш).","9":"А царь получил весть, что на него идет Тахарка, царь Куша…. И снова царь отправил посланников к Езекии, повелев им:","10":"«Передайте Езекии, царю Иудеи: „Пусть твой Бог, на которого ты надеешься, не обманывает тебя, обещая, что Иерусалим не будет отдан в руки царя ассирийского.","11":"Ты ведь знаешь, что сделали цари ассирийские со всеми странами – предали их огню и мечу! Неужели ты спасешься?","12":"Разве боги других народов сумели их спасти? Мои предки истребили эти народы – Гозан, Харран, Рецеф и обитателей Эдена, которые жили в Телассаре!","13":"Где сейчас цари Хамата, Арпада и города Сефарваим? Где цари Хены и Иввы?\"»","14":"Езекия взял у посланников свиток и прочел его. Затем он пошел в Храм Господа и развернул свиток пред Господом.","15":"И стал Езекия молиться Господу: «О Господь Воинств, Бог Израиля, Восседающий на херувимах! Ты единственный Бог для всех царств земли, Ты создал небо и землю.","16":"О Господь, вслушайся – и услышь! Открой, о Господь, очи Свои – и посмотри! Услышь слова Синаххериба, который отправил посланников, чтобы они оскорбляли Бога Живого.","17":"Это правда, о Господь, что цари ассирийские опустошили все народы и страны,","18":"а богов их предали огню. Но ведь то были не боги, а изделия рук человеческих, деревяшки и камни, – вот их и уничтожили.","19":"О Господь, Бог наш, спаси нас от врага! Пусть все царства земли узнают, что Ты, Господь, – единственный Бог!»","20":"Исайя, сын Амоца, велел передать Езекии: «Так говорит Господь, Бог Израиля: ты обратился ко Мне с мольбой, жалуясь на Синаххериба, царя ассирийского. Я услышал.","21":"Вот слово, которое изрекает о нем Господь: Дева – Сион презирает тебя, смеется она над тобой! Иерусалим головою качает, глядя тебе вслед.","22":"Кого ты поносишь? Кого хулишь? На кого возвышаешь голос? На кого глядишь свысока? На Святого Бога Израилева!","23":"Ты устами своих послов оскорбляешь Господа! Говоришь: „Колесниц у меня много, я с ними на горы восходил, на отроги Ливана! Высочайшие кедры Ливана срубил я, его лучшие кипарисы; взошел на его самую дальнюю гору, в самую чащу леса.","24":"Я колодцы выкапывал, воду пил чужих стран, я шагал, как посуху, по рекам Египта!\"","25":"Но разве не знаешь ты: Я давно готовил все это? То, что издревле Я задумал, теперь исполнено Мною: укрепленные города обратились в груды камней!","26":"Жители их бессильны, посрамлены они, в ужасе. Стали как травы в поле, как на лугу зелень, как поросль на крышах – иссохшие, иссушенные восточным ветром.","27":"Я знаю про каждый твой шаг – на месте ль ты, уходишь, приходишь – и про бунт твой против Меня!","28":"И за бунт твой против Меня, за шум твоих полчищ, достигший Моего слуха, Я воткну тебе крюк в ноздри, и узду в уста твои вдену, и назад уведу тебя той дорогой, по которой ты пришел!","29":"А тебе, Езекия, дается знак: В этот год ешьте хлеб, что сам уродился, во второй год – то, что взойдет само, а на третий год сейте и жните, сажайте лозу, виноград ешьте.","30":"Тогда уцелевший остаток потомков Иуды снова пустит корень вглубь, а вверху – принесет плоды.","31":"Уцелевшие выйдут из Иерусалима, спустятся выжившие с горы Сион. Ярость Господа Воинств сделает это!","32":"Так говорит Господь о царе ассирийском: Не войдет он в этот город и стрелу в него не пустит, не появится перед ним со щитом, не воздвигнет осадного вала.","33":"Уйдет он по той же дороге, по которой пришел. Он не войдет в этот город! – говорит Господь. –","34":"Я защищу этот город и спасу – ради Себя и ради Давида, раба Моего».","35":"В ту же ночь появился ангел Господа и умертвил в стане ассирийцев сто восемьдесят пять тысяч человек. Настало утро – и вот, кругом одни мертвые тела.","36":"…И Синаххериб, царь ассирийский, отступил и ушел восвояси. Он пребывал в Ниневии.","37":"Когда он совершал поклонение в храме своего бога Нисроха, Адраммелех и Сарецер, его сыновья, закололи его мечом и бежали в страну Урарту. Царем после него стал Асархаддон, его сын."},"20":{"1":"В ту пору Езекия заболел и был при смерти. Пророк Исайя, сын Амоца, пришел к нему и сказал: «Так говорит Господь: отдай последние распоряжения. Ты умираешь, не возвратиться тебе к жизни».","2":"Езекия отвернулся к стене и взмолился к Господу:","3":"«Вспомни, о Господь! Я вел пред Тобою жизнь честную и безупречную, делал то, что Тебе угодно!» Езекия горько заплакал.","4":"И вот, не успел еще Исайя выйти из дворца в Срединный Город – было ему слово Господа:","5":"«Вернись, скажи Езекии, правителю Моего народа: „Так говорит Господь, Бог твоего предка Давида: Я услышал твою мольбу, увидел твои слезы – и Я исцеляю тебя. Послезавтра ты войдешь в Храм Господа.","6":"Я продлеваю тебе жизнь на пятнадцать лет. И от царя Ассирии Я спасу и тебя, и этот город. Я встану на защиту этого города – ради Себя Самого и ради раба Моего Давида!\"»","7":"Исайя велел: «Пусть принесут лепешку сушеного инжира». Принесли, приложили к нарыву, и Езекия стал поправляться.","8":"Спросил Езекия Исайю: «Где знак, что Господь и вправду исцелит меня и я послезавтра пойду в Храм Господа?»","9":"Исайя сказал: «Вот тебе от Господа знак, что Господь исполнит Свое обещание. Тень, что уже спустилась на десять ступеней, – может ли вернуться на десять ступеней обратно?»","10":"Ответил Езекия: «Тень может спуститься на десять ступеней. Но не вернуться ей на десять ступеней обратно!»","11":"Тогда воззвал пророк Исайя к Господу, – и Господь вернул тень, что спустилась по ступеням лестницы Ахаза, назад, на десять ступеней вверх.","12":"В то время вавилонский царь Меродах – Баладан, сын Баладана, услышав, что Езекия болен, отправил ему послание и дары.","13":"Езекия выслушал послов и показал им свою сокровищницу: серебро, и золото, и благовония, и драгоценное масло, и весь склад оружия – все, что было в его хранилищах. Что только было у Езекии во дворце и во всем его государстве – все показал он им.","14":"Пророк Исайя пришел к царю Езекии и спросил: «Что говорят эти люди, и откуда они прибыли к тебе?» Езекия ответил: «Они прибыли из далекой страны, из Вавилонии».","15":"Пророк спросил: «Что они видели у тебя во дворце?» Езекия ответил: «У меня во дворце они видели все. Что только есть у меня в хранилищах – все показал я им».","16":"И тогда Исайя сказал Езекии: «Слушай слово Господа:","17":"наступят дни, когда все, что есть в твоем дворце, все, что скопили твои предки, будет увезено в Вавилон, и не останется здесь ничего, – говорит Господь. –","18":"И твои потомки – отпрыски твоего рода, наследники твои – будут взяты в плен и станут евнухами при дворе царя вавилонского».","19":"На это Езекия ответил Исайе: «Слово Господа, что ты сейчас возвестил, – добрая весть. Значит, пока я жив, – сказал Езекия, – здесь будут мир и безопасность».","20":"Прочее о деяниях Езекии и его доблести, и о том, как он устроил пруд, прорыл канал и провел в город воду, написано в «Летописях царей Иудеи».","21":"И упокоился Езекия со своими предками. Царем после него стал его сын Манассия."},"21":{"1":"Двенадцати лет от роду Манассия стал царем; пятьдесят пять лет царствовал он в Иерусалиме; имя его матери – Хефцивах.","2":"Он творил дела, ненавистные Господу, – он совершал такие же гнусности, как и те народы, чью землю Господь отдал израильтянам.","3":"Он восстановил капища, уничтоженные его отцом Езекией; построил жертвенники Ваалу; воздвиг древо Ашеры, как Ахав, царь Израиля. Он поклонялся всему воинству небесному и служил ему.","4":"Даже в Храме Господа, о котором Господь сказал: «В Иерусалиме пребывать будет имя Мое» – Манассия понастроил жертвенников.","5":"В обоих дворах Храма Господа он построил жертвенники всему воинству небесному.","6":"Он принес в огненную жертву собственного сына. Он ворожил и гадал, вызывал мертвецов и духов – ведунов – делал много дел, ненавистных Господу, оскорблял Господа.","7":"Он велел изготовить статую Ашеры и поставить в том самом Храме, о котором Господь говорил Давиду и его сыну Соломину: «В этом Храме, в Иерусалиме – городе, который Я выбрал Себе из всех владений племен Израилевых, Мое имя будет пребывать вовеки.","8":"Никогда больше Я не заставлю израильтян скитаться на чужбине, вдали от страны, которую Я отдал их отцам. Только пусть они строго соблюдают и исполняют все, что Я им повелел – соблюдают Закон, который дал им Мой раб Моисей!»","9":"А они не вняли! Манассия сбил их с пути, и они стали поступать еще хуже, чем те народы, которые Господь истребил, чтобы дать место израильтянам.","10":"И тогда Господь возвестил через пророков, рабов своих:","11":"«Манассия, царь Иудеи, совершал такие гнусности, что превзошел даже амореев, своих предшественников; он и Иудею своими идолами вверг в грех.","12":"За это, – говорит Господь, Бог Израиля, – Я скоро наведу на Иерусалим и на Иудею такую беду, что у всякого, кто о ней услышит, в ушах зазвенит.","13":"Я протяну над Иерусалимом тот же мерный шнур, что и над Самарией, – тот же отвес, что и над домом Ахава! Я сотру Иерусалим, как грязь стирают с миски – вытирают и переворачивают кверху дном.","14":"Все, что еще осталось от достояния Моего, Я отвергну, отдам в руки врага, неприятелю на разграбление.","15":"С тех пор, как вышли их отцы из Египта, и доныне, эти люди без конца совершают дела, ненавистные Мне, непрестанно оскорбляют Меня!»","16":"А еще, вдобавок к тому, что он ввел Иудею в грех и заставил людей совершать дела, ненавистные Господу, Манассия убил множество невинных людей – весь Иерусалим залил кровью.","17":"Прочее о деяниях Манассии и о грехах, им совершенных, написано в «Летописях царей Иудеи».","18":"Манассия отошел к отцам и был похоронен в саду своего дворца – в саду Уззы. Царем после него стал его сын Амон.","19":"Двадцати двух лет от роду Амон стал царем; два года царствовал он в Иерусалиме; имя его матери – Мешуллемет, дочь Харуца, из Иотвы .","20":"Его дела были так же ненавистны Господу, как и дела его отца, Манассии.","21":"Во всем он следовал отцу, шел тем же путем. Он служил тем же идолам, которым служил его отец, и поклонялся им,","22":"а Господа, Бога своих отцов, оставил – не стал ходить путями Господа.","23":"Приближенные Амона составили против него заговор и убили его прямо во дворце.","24":"Но народ перебил всех заговорщиков и провозгласил царем Иосию, сына Амона.","25":"Прочее о деяниях Амона написано в «Летописях царей Иудеи».","26":"Похоронен он был в своей гробнице, в саду Уззы. Царем после него стал Иосия, его сын."},"22":{"1":"Восьми лет от роду Иосия стал царем; тридцать один год царствовал он в Иерусалиме; имя его матери – Иедида, дочь Адаи, из Боцката.","2":"Он творил дела, угодные Господу. Во всем следовал он отцу своему Давиду, шел его путем, не уклоняясь ни вправо, ни влево.","3":"На восемнадцатый год своего царствования Иосия послал писца Шафана, сына Ацалии, сына Meшуллама, в Храм Господа с таким приказом:","4":"«Ступай к Хилкие , верховному священнику. Вели ему переплавить все серебро, поступившее в Храм Господа, – все серебро, которое стражи ворот собрали с народа, –","5":"и передать тем, кто назначен вести работы в Храме Господа. Пусть из этих денег оплачивают труд рабочих, которые ремонтируют Храм Господа:","6":"плотников, строителей и каменщиков, а также покупку дерева и тесаного камня, сколько нужно для ремонта Храма.","7":"С тех, кому эти деньги будут переданы, отчета требовать не нужно, им можно доверять».","8":"Хилкия, верховный священник, сказал Шафану – писцу: «Я нашел в Храме Господа книгу Закона!» И Хилкия передал свиток Шафану. Тот прочел его.","9":"Шафан – писец пришел к царю с отчетом: «Рабы твои переплавили серебро, поступившее в Храм, и передали тем, кто назначен ремонтировать Храм Господа».","10":"Потом добавил: «Священник Хилкия передал мне свиток». И Шафан прочел свиток царю.","11":"Выслушал царь, что написано в книге Закона, и разодрал одежды свои.","12":"Он повелел священнику Хилкии, Ахикаму, сыну Шафана, Ахбору, сыну Михея, писцу Шафану и Асае , царскому слуге:","13":"«Идите, вопросите Господа обо мне, о народе и обо всей Иудее: как быть с тем, что написано в этой найденной ныне книге? О, как же силен должен быть гнев Господа против нас за то, что наши отцы не вняли словам этой книги и не поступали так, как нам в ней предписано!»","14":"И пошли священник Хилкия, Ахикам, Ахбор, Шафан и Асая к пророчице Хулде , жене Шаллума, сына Тиквы, сына Хархаса, хранителя одежд. Жила она в Иерусалиме, в Новом городе. Они все рассказали ей,","15":"и она ответила: «Так говорит Господь, Бог Израиля! Передайте тому, кто послал вас ко мне:","16":"„Так говорит Господь: скоро, скоро Я наведу на этот город и на его жителей страшную беду; исполнится все, что сказано в книге, которую прочел царь Иудеи.","17":"Эти люди оставили Меня, они приносили жертвы другим богам, они всеми своими поступками оскорбляли Меня! За это, как огонь, воспламенится Моя ярость против этого города – и не угаснет!\"","18":"А царю Иудеи, который послал вас вопросить Господа, передайте: „Так говорит Господь, Бог Израиля: ты слышал, что написано в этой книге.","19":"Услышав, что Я обещал сделать с этим городом и с его жителями, – что он будет предан опустошению и проклятию, – ты смирился и склонился перед Господом, и разодрал одежды и плакал передо Мной. За это и Я услышал тебя, – говорит Господь. –","20":"Я дам тебе спокойно отойти к отцам, ты будешь с миром погребен в своей гробнице, и глаза твои не увидят той страшной беды, которую Я наведу на этот город\"». Ответ пророчицы передали царю."},"23":{"1":"Царь повелел, чтобы к нему собрали всех старейшин Иудеи и Иерусалима.","2":"Он вошел в Храм Господа, а следом за ним все жители Иудеи и Иерусалима, священники, пророки и весь народ, стар и млад. И царь прочел им от начала до конца всю Книгу договора, что была найдена в Храме Господа.","3":"Царь встал на помосте и заключил с Господом договор о верности: быть верным Господу, от всего сердца и от всей души исполнять Его повеления, предписания и законы, соблюдать все условия договора, записанные в свитке. И весь народ принял этот договор.","4":"Царь приказал верховному священнику Хилкии, а также священникам – помощникам и стражам ворот убрать из Храма Господнего все, что было предназначено для служения Ваалу, Ашере и воинству небесному. Все это царь велел сжечь вне Иерусалима, на склонах Кедронского оврага, а пепел отнести в Бет – Эль.","5":"Он убрал жрецов, которых цари Иудеи назначали приносить жертвы на капищах в городах Иудеи и в окрестностях Иерусалима, а также тех жрецов, что приносили жертвы Ваалу, Солнцу, Луне, созвездиям и всему воинству небесному.","6":"Он велел вынести Ашеру из Храма Господнего за стены Иерусалима, в Кедронский овраг. Там он ее сжег, стер в пыль, а пыль выбросил на кладбище.","7":"Он уничтожил и помещения для «посвященных», бывшие при Храме Господа (там женщины ткали одеяния для Ашеры).","8":"Он отозвал жрецов из всех городов Иудеи и осквернил все капища – от Гевы и до Беэр – Шевы – на которых эти жрецы приносили жертвы. Уничтожил и Капище у ворот (то, что перед воротами Иисуса – градоначальника, слева, у городских ворот).","9":"Жрецам упраздненных капищ не дозволено было служить при жертвеннике Господа в Иерусалиме, но им было разрешено есть пресный хлеб вместе с другими священниками.","10":"Он осквернил Тофет, что в долине Бен – Хинном, чтобы никто больше не приносил сына или дочь в огненную жертву Молоху.","11":"Он убрал лошадей, которых цари Иудеи посвятили Солнцу (они были у входа в Храм Господа, близ покоев Нетанмелеха – евнуха, во дворе), а колесницы Солнца сжег.","12":"Он разрушил жертвенники, воздвигнутые царями Иудеи на крыше верхних покоев Ахаза, а также жертвенники, сделанные Манассией в обоих дворах Храма Господа. Он разбил их на куски, стер их в пыль, а пыль выбросил в Кедронский овраг.","13":"Осквернил царь и капища, что были к востоку от Иерусалима, южнее Погибельной горы (их построил Соломон, царь Израиля, для Астарты – мерзости сидонской, для Кемоша – мерзости моавской и для Милкома – аммонской мрази).","14":"Он разбил священные камни, срубил дерева Ашеры, а место, где они стояли, забросал человеческими костями.","15":"И тот жертвенник, что стоял в Бет – Эле в капище, построенном Иеровоамом, сыном Невата, который повел Израиль по греховному пути, царь уничтожил вместе с капищем. Сжег он капище, стер его в пыль, и древо Ашеры сжег.","16":"Оглянулся Иосия, увидел на горе кладбище и приказал принести кости из гробниц и сжечь эти кости на жертвеннике, чтобы осквернить его: исполнилось слово Господа, возвещенное человеком Божьим.","17":"«Что это за памятник?» – спросил Иосия. Жители города ответили: «Это могила человека Божьего, который пришел из Иудеи и предсказал все, что ты сделал сейчас с жертвенником в Бет – Эле». –","18":"«Оставьте эту могилу, – велел Иосия. – Пусть никто не трогает его останки». И люди Иосии пощадили эти останки – а с ними вместе и останки пророка, пришедшего из Самарии.","19":"Иосия уничтожил все храмы – капища, какие цари Израиля, оскорбляя Господа, понастроили в городах Самарии. Со всеми этими капищами он поступал так же, как с бет – эльским капищем.","20":"Он закалывал жрецов этих капищ на их жертвенниках и сжигал на жертвенниках человеческие кости. Вернувшись в Иерусалим,","21":"царь повелел всему народу: «Совершайте Пасху для Господа, вашего Бога, как предписано в Книге договора».","22":"Пасха не праздновалась с тех самых пор, как Израилем правили Судьи, – все время, что царствовали цари Израиля и Иудеи.","23":"Но в восемнадцатый год царствования Иосии была совершена в Иерусалиме Пасха для Господа.","24":"Иосия сделал так, что не стало больше ни вызывателей мертвецов и духов – ведунов, ни терафимов, ни идолов, ни прочей мерзости, которая бытовала прежде в Иудее и Иерусалиме. Так выполнял он слова Закона из книги, которую Хилкия – священник нашел в Храме Господа.","25":"Не бывало прежде такого царя – который так обратился бы к Господу всем сердцем, всей душой и всем существом своим, и во всем следовал Закону Моисея. Да и после Иосии не было таких, как он.","26":"Но не утих великий гнев Господа на Иудею за все те бесчинства, которыми Манассия оскорбил Господа.","27":"Господь сказал: «Я отвергну Иудею, как отверг Израиль. Я оставлю Мой избранный город – Иерусалим. Оставлю Храм, о котором сказал: „Здесь пребывать будет имя Мое\"».","28":"Прочее о деяниях Иосии написано в «Летописях царей Иудеи».","29":"В ту пору фараон Нехо, царь Египта, выступил в поход на царя Ассирийского, к Евфрату. Царь Иосия пошел ему навстречу. В Мегиддо, увидев Иосию, фараон убил его.","30":"Приближенные царя привезли убитого из Мегиддо в Иерусалим и похоронили в его гробнице. Люди взяли Иоахаза, сына Иосии, и помазали его на царство, сделали царем.","31":"Двадцати трех лет от роду Иоахаз стал царем; три месяца царствовал он в Иерусалиме; имя его матери – Хамуталь, дочь Иеремии, из Ливны.","32":"Его дела были так же ненавистны Господу, как и дела его отцов.","33":"В Ривле, что в стране Хамат, фараон Нехо взял его под стражу, лишив иерусалимского престола, а на иудейскую страну наложил дань – сто талантов серебра и талант золота.","34":"Фараон Нехо возвел Элиакима, сына Иосии, на престол Иосии, отца его, и дал ему новое имя Иоаким. А Иоахаза фараон увел в Египет, там он и умер.","35":"Иоаким выплатил фараону и серебро, и золото. Чтобы собрать столько, сколько требовал фараон, Иоаким разложил эту дань на всех жителей страны. С каждого – смотря по тому, какое было у кого состояние, – взимал он серебро и золото для фараона Нехо.","36":"Двадцать пять лет было Иоакиму, когда он стал царем; одиннадцать лет он царствовал в Иерусалиме; имя его матери – Зевуда, дочь Педаи, из Румы .","37":"Его дела были так же ненавистны Господу, как и дела его отцов."},"24":{"1":"Во дни Иоакима Навуходоносор, царь Вавилона, пошел на него войной. Иоаким сперва признал над собой его власть, но через три года восстал.","2":"И тогда Господь наслал на него полчища халдеев, арамеев, моавитян и аммонитян – всех их наслал на Иудею, чтобы уничтожить ее. Сбылось слово Господа, возвещенное Его рабами, пророками.","3":"Решил Господь отвергнуть Иудею – за грехи Манассии, за все, что он сделал,","4":"за кровь невинных, которой он залил Иерусалим! Прощать Господь уже не хотел.","5":"Прочее о деяниях Иоакима написано в «Летописях царей Иудеи».","6":"Иоаким отошел к отцам, царем после него стал Иехония, его сын.","7":"Царь Египта больше не покидал пределов своей страны, а царь Вавилона захватил все, что когда-то принадлежало царю Египта, от Египетской ложбины до Евфрата.","8":"Восемнадцати лет от роду Иехония стал царем; три месяца царствовал он в Иерусалиме; имя его матери – Нехушта, дочь Элнатана, из Иерусалима.","9":"Его дела были так же ненавистны Господу, как и дела его отца.","10":"Тем временем военачальники Навуходоносора, царя вавилонского, двинулись на Иерусалим и осадили его.","11":"Когда прибыл Навуходоносор, царь Вавилона – город уже был в осаде –","12":"Иехония, царь Иудеи, сдался царю Вавилона вместе со своей матерью, сановниками, военачальниками и придворными. Царь Вавилона взял его в плен на восьмой год своего царствования.","13":"Навуходоносор унес из Храма Господа и из царского дворца все сокровища, разломав на части всю золотую утварь, сделанную Соломоном для Храма Господа. Сбылось слово Господа!","14":"Он выселил всех жителей Иерусалима: всех сановников и всех видных людей, общим числом десять тысяч человек, а также всех ремесленников и кузнецов. Осталась одна беднота.","15":"Он увел Иехонию в Вавилон и переселил из Иерусалима в Вавилон царицу – мать, царских жен, придворных, всю знать страны.","16":"Семь тысяч зажиточных людей, тысячу ремесленников и кузнецов, всех воинов переселил он из Иерусалима в Вавилон.","17":"Вместо Иехонии вавилонский царь возвел на престол Маттанию, его дядю, и дал ему новое имя Седекия.","18":"Двадцать один год было Седекии, когда он стал царем; одиннадцать лет царствовал он в Иерусалиме; имя его матери – Хамуталь, дочь Иеремии, из Ливны.","19":"Его дела были так же ненавистны Господу, как и дела Иоакима.","20":"Гнев Господень против Иерусалима и Иудеи был столь силен, что Господь отверг их и отвернулся от них. И Седекия восстал против вавилонского царя."},"25":{"1":"В девятый год царствования Седекии, в десятый день десятого месяца, Навуходоносор, царь Вавилона, со всем своим войском подошел к Иерусалиму. Он осадил город и окружил его валом.","2":"Осада продолжалась до одиннадцатого года царствования Седекии.","3":"В девятый день четвертого месяца (в городе в это время свирепствовал голод, народу нечего было есть)","4":"городская стена была проломлена. Тогда все воины вышли ночью через Ворота Двух Стен, что у царского сада (а город в то время был окружен халдеями), и пошли по дороге на Араву.","5":"Войско халдеев пустилось в погоню за царем и настигло его в пустыне близ Иерихона. Все воины царя разбежались,","6":"а его самого схватили, привели к царю Вавилона в Ривлу и там судили.","7":"Сыновей Седекии зарезали у него на глазах, затем самого его ослепили, заковали в кандалы и увели в Вавилон.","8":"В седьмой день пятого месяца, в девятнадцатый год правления Навуходоносора, царя вавилонского, в Иерусалим прибыл Навузарадан, начальник телохранителей, один из приближенных вавилонского царя.","9":"Он сжег Храм Господа, царский дворец и все дома в Иерусалиме – все большие здания он сжег дотла.","10":"И крепостные стены вокруг Иерусалима тоже разрушили халдейские воины Навузарадана.","11":"Всех, кто еще уцелел в городе, включая перебежчиков, перешедших на сторону вавилонского царя, – всех Навузарадан, начальник телохранителей, отправил в Вавилон.","12":"Лишь самую бедноту он оставил в стране, работать в виноградниках и на полях.","13":"Медные столбы из Храма Господа, и подставки, и Медное Море, что в Храме Господа, халдеи разломали, а медь увезли в Вавилон.","14":"Взяли они и котлы, и кадильницы, и щипцы, и ковши – всю медную утварь, которая использовалась при богослужении.","15":"Взял начальник телохранителей и лотки, и чаши для возлияния, и все золото, и все серебро.","16":"Две колонны, и одно медное море, и подставки, которые сделал Соломон, чтобы стояли в Храме Господа, – сколько было меди во всем этом, не счесть!","17":"Каждая колонна была восемнадцати локтей в высоту; у каждой медная капитель высотой в три локтя. Вокруг капителей у обеих колонн – сетка и плоды граната, все из меди.","18":"Начальник телохранителей забрал первосвященника Сераю, второго священника Софонию и трех стражей ворот.","19":"Он также забрал из города сановника, который командовал воинами, пятерых человек из свиты царя, которых нашел в городе, писца, который начальствовал над войском и занимался набором ополчения, и еще шестьдесят знатных людей, которых нашел в городе.","20":"Навузарадан, начальник телохранителей, привел их к царю Вавилона в Ривлу.","21":"И там, в Ривле, что в стране Хамат, царь казнил их всех. Так иудеи были выселены со своей земли.","22":"А над теми, кто остался в Иудее, кому Навуходоносор, царь Вавилона, разрешил остаться, он поставил Гедалию, сына Ахикама, сына Шафана.","23":"Узнав о том, что царь Вавилона сделал Гедалию своим наместником, все иудейские военачальники вместе со своими людьми пришли к нему в Мицпу: Измаил, сын Нетании; Иоханан, сын Кареаха; Серая, сын Танхумета, из Нетофы; и Яазания из Маахи .","24":"Гедалия, сын Ахикама, сын Шафана, поклялся им и их людям: «Не бойтесь халдейских чиновников, оставайтесь в стране, служите царю Вавилона и будет вам хорошо!»","25":"В седьмой месяц пришел Измаил, сын Нетании, сына Элишамы, царский родственник, и с ним десять человек, и они убили Гедалию, а также иудеев и халдеев, которые были с ним в Мицпе.","26":"Тогда поднялись все иудеи, от мала до велика, вместе с военачальниками, и ушли в Египет, боясь халдеев.","27":"В тридцать седьмой год после пленения Иехонии, царя Иудеи, в двадцать седьмой день двенадцатого месяца, Эвил – Меродах, ставший в тот год царем Вавилона, помиловал Иехонию, царя Иудеи, и освободил его из тюрьмы.","28":"Он говорил с ним дружелюбно, велел ему сидеть выше всех остальных царей, которые были при Эвил – Меродахе в Вавилоне,","29":"и приказал дать ему новую одежду, вместо прежней, что была на нем в тюрьме. С тех пор и до конца дней своих Иехония ел за столом царя вавилонского.","30":"И он получал постоянное содержание от вавилонского царя – ежедневно, до конца дней своих."}};
